  1→//! Property-based tests for parser pattern matching
  2→//!
  3→//! Tests two key functions:
  4→//! - `expand_pattern`: Placeholder expansion ({page_id}, {aud})
  5→//! - `matches_wildcard`: Path-segment wildcard matching (*)
  6→
  7→use super::*;
  8→use crate::test_strategies::*;
  9→use proptest::prelude::*;
 10→
 11→// Pattern Expansion Properties
 12→
 13→proptest! {
 14→    /// Expansion properties: idempotent, removes placeholders, preserves literals, exact values
 15→    #[test]
 16→    fn test_expand_properties(
 17→        pattern in layer_pattern_with_placeholders(),
 18→        prefix in segment_strategy(),
 19→        suffix in segment_strategy(),
 20→        page_id in page_id_strategy(),
 21→        did in did_strategy(),
 22→    ) {
 23→        // Idempotent
 24→        let once = expand_pattern(&pattern, &page_id, &did);
 25→        let twice = expand_pattern(&once, &page_id, &did);
 26→        prop_assert_eq!(&once, &twice, "Expansion should be idempotent");
 27→
 28→        // Removes all known placeholders
 29→        for p in &["{page_id}/data", "{page_id}/orders/{aud}", "{aud}/{page_id}"] {
 30→            let result = expand_pattern(p, &page_id, &did);
 31→            prop_assert!(!result.contains("{page_id}"), "Should expand page_id in {}", p);
 32→            prop_assert!(!result.contains("{aud}"), "Should expand aud in {}", p);
 33→        }
 34→
 35→        // Preserves literal segments
 36→        let lit_pattern = format!("{}/{{page_id}}/{}", prefix, suffix);
 37→        let lit_result = expand_pattern(&lit_pattern, &page_id, &did);
 38→        prop_assert!(lit_result.starts_with(&prefix), "Prefix should be preserved");
 39→        prop_assert!(lit_result.ends_with(&suffix), "Suffix should be preserved");
 40→
 41→        // Exact substitution
 42→        prop_assert_eq!(expand_pattern("{page_id}", &page_id, &did), page_id.clone());
 43→        prop_assert_eq!(expand_pattern("{aud}", &page_id, &did), did.clone());
 44→
 45→        // Empty inputs don't crash
 46→        let _ = expand_pattern(&pattern, "", "");
 47→        let _ = expand_pattern("", "page123", "did:key:abc");
 48→    }
 49→}
 50→
 51→// Wildcard Matching Properties
 52→
 53→proptest! {
 54→    /// Exact match is reflexive: layer matches itself
 55→    #[test]
 56→    fn exact_match_is_reflexive(layer in layer_name_strategy()) {
 57→        prop_assert!(matches_wildcard(&layer, &layer), "Layer should match itself: {}", layer);
 58→    }
 59→
 60→    /// Single wildcard matches any single segment
 61→    #[test]
 62→    fn wildcard_matches_any_segment(
 63→        prefix in segment_strategy(),
 64→        middle in segment_strategy(),
 65→        suffix in segment_strategy(),
 66→    ) {
 67→        let layer = format!("{}/{}/{}", prefix, middle, suffix);
 68→        let pattern = format!("{}/*/{}",  prefix, suffix);
 69→        prop_assert!(matches_wildcard(&layer, &pattern),
 70→            "Pattern {} should match layer {}", pattern, layer);
 71→    }
 72→
 73→    /// Segment count must match exactly (core invariant)
 74→    #[test]
 75→    fn segment_count_must_match(
 76→        segments in prop::collection::vec(segment_strategy(), 2..5),
 77→    ) {
 78→        let layer = segments.join("/");
 79→        let fewer = segments[..segments.len()-1].join("/");
 80→        let more = format!("{}/extra", layer);
 81→
 82→        prop_assert!(
 83→            !matches_wildcard(&layer, &fewer),
 84→            "Layer {} should not match pattern {} (fewer segments)", layer, fewer
 85→        );
 86→        prop_assert!(
 87→            !matches_wildcard(&layer, &more),
 88→            "Layer {} should not match pattern {} (more segments)", layer, more
 89→        );
 90→    }
 91→
 92→    /// Multiple wildcards work independently
 93→    #[test]
 94→    fn multiple_wildcards_work(
 95→        seg1 in segment_strategy(),
 96→        seg2 in segment_strategy(),
 97→        seg3 in segment_strategy(),
 98→    ) {
 99→        let layer = format!("{}/{}/{}", seg1, seg2, seg3);
100→        prop_assert!(matches_wildcard(&layer, "*/*/*"),
101→            "All wildcards should match: {}", layer);
102→        prop_assert!(matches_wildcard(&layer, &format!("*/{}/{}", seg2, seg3)),
103→            "Prefix wildcard should match: {}", layer);
104→        prop_assert!(matches_wildcard(&layer, &format!("{}/*/{}",seg1, seg3)),
105→            "Middle wildcard should match: {}", layer);
106→        prop_assert!(matches_wildcard(&layer, &format!("{}/{}/*", seg1, seg2)),
107→            "Suffix wildcard should match: {}", layer);
108→    }
109→
110→    /// Different segments don't match (non-wildcard)
111→    #[test]
112→    fn different_segments_dont_match(
113→        seg1 in segment_strategy(),
114→        seg2 in segment_strategy(),
115→    ) {
116→        prop_assume!(seg1 != seg2);
117→        prop_assert!(!matches_wildcard(&seg1, &seg2),
118→            "Different segments should not match: {} vs {}", seg1, seg2);
119→    }
120→
121→    /// Wildcard only matches complete segment, not partial
122→    #[test]
123→    fn wildcard_is_complete_segment(
124→        prefix in segment_strategy(),
125→        extra in segment_strategy(),
126→    ) {
127→        // Pattern "*" should match "orders" but not "orders/sub"
128→        let simple_layer = prefix.clone();
129→        let nested_layer = format!("{}/{}", prefix, extra);
130→
131→        prop_assert!(matches_wildcard(&simple_layer, "*"),
132→            "Single wildcard should match single segment");
133→        prop_assert!(!matches_wildcard(&nested_layer, "*"),
134→            "Single wildcard should NOT match nested path: {}", nested_layer);
135→    }
136→}
137→
138→// Example-based Documentation Tests
139→
140→#[test]
141→fn doc_pattern_expansion() {
142→    assert_eq!(
143→        expand_pattern("{page_id}/orders/{aud}", "shop123", "did:key:abc"),
144→        "shop123/orders/did:key:abc"
145→    );
146→    assert_eq!(
147→        expand_pattern("{page_id}/data", "mypage", "viewer123"),
148→        "mypage/data"
149→    );
150→}
151→
152→#[test]
153→fn doc_wildcard_segment_matching() {
154→    // Wildcard matches single segment
155→    assert!(matches_wildcard("shop/orders/customer", "shop/*/customer"));
156→    assert!(matches_wildcard("a/b/c", "*/*/c"));
157→
158→    // Segment count MUST match
159→    assert!(!matches_wildcard("shop/orders/customer", "shop/*"));
160→    assert!(!matches_wildcard("a/b", "a/b/c"));
161→    assert!(!matches_wildcard("a/b/c", "a/b"));
162→
163→    // Exact match works
164→    assert!(matches_wildcard("orders", "orders"));
165→    assert!(!matches_wildcard("orders", "products"));
166→}
167→
168→#[test]
169→fn doc_empty_pattern_edge_cases() {
170→    // Empty strings
171→    assert!(matches_wildcard("", ""));
172→    assert!(!matches_wildcard("a", ""));
173→    assert!(!matches_wildcard("", "a"));
174→
175→    // Single segment
176→    assert!(matches_wildcard("a", "a"));
177→    assert!(matches_wildcard("a", "*"));
178→}
179→
180→// Real-world permit template patterns (from sample_apps)
181→
182→#[test]
183→fn test_real_world_patterns() {
184→    // Shop patterns
185→    let page_id = "shop123abc";
186→    let customer_did = "did:key:z6MkCustomer123";
187→
188→    assert_eq!(
189→        expand_pattern("{page_id}/products", page_id, customer_did),
190→        "shop123abc/products"
191→    );
192→    assert_eq!(
193→        expand_pattern("{page_id}/derived/orders_summary", page_id, customer_did),
194→        "shop123abc/derived/orders_summary"
195→    );
196→
197→    let orders_expanded = expand_pattern("{page_id}/orders/*", page_id, customer_did);
198→    assert!(matches_wildcard(
199→        "shop123abc/orders/customer1",
200→        &orders_expanded
201→    ));
202→    assert!(matches_wildcard(
203→        "shop123abc/orders/did:key:abc",
204→        &orders_expanded
205→    ));
206→
207→    let customer_orders = expand_pattern("{page_id}/orders/{aud}", page_id, customer_did);
208→    assert!(matches_wildcard(
209→        "shop123abc/orders/did:key:z6MkCustomer123",
210→        &customer_orders
211→    ));
212→    assert!(!matches_wildcard(
213→        "shop123abc/orders/did:key:z6MkOther456",
214→        &customer_orders
215→    ));
216→
217→    // Booking patterns
218→    let page_id = "booking789";
219→    let customer_did = "did:key:z6MkBookingUser";
220→
221→    assert_eq!(
222→        expand_pattern("{page_id}/schedule", page_id, customer_did),
