243→#[test]
244→fn real_world_app_layers() {
245→    // App layers use colon syntax (no placeholders, but colon separator)
246→    // These should be exact matches when expanded (no wildcards)
247→    let page_id = "demo123";
248→    let did = "did:key:z6MkUser";
