262→
263→#[test]
264→fn real_world_drafts_local_only() {
265→    // Drafts layer: {page_id}/drafts with sync=false (local only)
266→    let page_id = "page456";
267→    let did = "did:key:z6MkUser";
268→
269→    let drafts_pattern = "{page_id}/drafts";
270→    let drafts_expanded = expand_pattern(drafts_pattern, page_id, did);
271→    assert_eq!(drafts_expanded, "page456/drafts");
