281→// Complex Pattern Interaction Tests
282→
283→#[test]
284→fn complex_owner_vs_viewer_pattern_isolation() {
285→    // Scenario: Owner has wildcard access, viewer has identity-scoped access
286→    // This tests the core isolation model of the permit system
287→
288→    let page_id = "shop123";
289→    let owner_did = "did:key:z6MkOwner";
290→    let viewer1_did = "did:key:z6MkViewer1";
291→    let viewer2_did = "did:key:z6MkViewer2";
292→
293→    // Owner pattern: {page_id}/orders/* (sees ALL orders)
294→    let owner_pattern = expand_pattern("{page_id}/orders/*", page_id, owner_did);
295→
296→    // Viewer patterns: {page_id}/orders/{aud} (sees only THEIR orders)
297→    let viewer1_pattern = expand_pattern("{page_id}/orders/{aud}", page_id, viewer1_did);
298→    let viewer2_pattern = expand_pattern("{page_id}/orders/{aud}", page_id, viewer2_did);
299→
300→    // Layer names that would exist
301→    let viewer1_orders = format!("{}/orders/{}", page_id, viewer1_did);
302→    let viewer2_orders = format!("{}/orders/{}", page_id, viewer2_did);
303→
304→    // Owner can see both
305→    assert!(matches_wildcard(&viewer1_orders, &owner_pattern));
306→    assert!(matches_wildcard(&viewer2_orders, &owner_pattern));
307→
308→    // Viewer1 can only see their orders
309→    assert!(matches_wildcard(&viewer1_orders, &viewer1_pattern));
310→    assert!(!matches_wildcard(&viewer2_orders, &viewer1_pattern));
311→
312→    // Viewer2 can only see their orders
313→    assert!(!matches_wildcard(&viewer1_orders, &viewer2_pattern));
314→    assert!(matches_wildcard(&viewer2_orders, &viewer2_pattern));
315→}
