317→#[test]
318→fn complex_nested_resource_hierarchy() {
319→    // Scenario: Deeply nested resource paths
320→    // e.g., {page_id}/spaces/{space_id}/documents/{doc_id}/comments
321→
322→    let page_id = "workspace001";
323→    let user_did = "did:key:z6MkUser";
324→
325→    // Various nesting levels
326→    let patterns = [
327→        "{page_id}/spaces",
328→        "{page_id}/spaces/{aud}",
329→        "{page_id}/spaces/{aud}/documents",
330→        "{page_id}/spaces/{aud}/documents/*",
331→    ];
332→
333→    let expanded: Vec<String> = patterns
334→        .iter()
335→        .map(|p| expand_pattern(p, page_id, user_did))
336→        .collect();
337→
338→    assert_eq!(expanded[0], "workspace001/spaces");
339→    assert_eq!(expanded[1], format!("workspace001/spaces/{}", user_did));
