258→// EDGE CASES
259→
260→#[test]
261→fn test_permit_edge_cases() {
262→    // No layers permit
263→    let no_layers = edge_case("no_layers", "page1", "did:key:user");
264→    assert!(!no_layers.can_write_layer("page1/anything", "page1", "did:key:user"));
265→    assert!(!no_layers.can_read_layer("page1/anything", "page1", "did:key:user"));
266→
267→    // Explicit layers (was "only_patterns" — now has explicit layer entries)
268→    let only_patterns = edge_case("only_patterns", "page1", "did:key:user");
269→    assert!(only_patterns.can_read_layer("page1/anything", "page1", "did:key:user"));
270→    assert!(!only_patterns.can_write_layer("page1/anything", "page1", "did:key:user"));
271→    assert!(only_patterns.can_read_layer("page1/foo", "page1", "did:key:user"));
272→    // Unlisted layers are not accessible
273→    assert!(!only_patterns.can_read_layer("page1/foo/bar", "page1", "did:key:user"));
274→    assert!(!only_patterns.can_read_layer("page1/unlisted", "page1", "did:key:user"));
275→
276→    // Deep nesting (explicit layers, no patterns)
277→    let deep = edge_case("deep_nesting", "page1", "did:key:user");
278→    assert!(deep.can_write_layer("page1/a/b/c/d", "page1", "did:key:user"));
279→    assert!(deep.can_write_layer("page1/x/y/z", "page1", "did:key:user"));
280→    assert!(deep.can_write_layer("page1/x/y/anything", "page1", "did:key:user"));
281→    // Not in permit → no access
282→    assert!(!deep.can_write_layer("page1/x/y/other", "page1", "did:key:user"));
283→
284→    // Colon layers
285→    let colon = edge_case("colon_layers", "page1", "did:key:user");
286→    assert!(colon.can_write_layer("app:MyApp", "page1", "did:key:user"));
287→
288→    // Write no sync
289→    let wns = edge_case("write_no_sync", "page1", "did:key:user");
290→    assert!(wns.can_write_layer("page1/local", "page1", "did:key:user"));
291→    assert!(!wns.should_sync_layer("page1/local", "page1", "did:key:user"));
292→
293→    // Sync no write
294→    let snw = edge_case("sync_no_write", "page1", "did:key:user");
295→    assert!(!snw.can_write_layer("page1/readonly", "page1", "did:key:user"));
296→    assert!(snw.can_read_layer("page1/readonly", "page1", "did:key:user"));
297→    assert!(snw.should_sync_layer("page1/readonly", "page1", "did:key:user"));
298→
299→    // Unknown layer defaults
300→    assert!(!snw.can_read_layer("page1/unknown", "page1", "did:key:user"));
301→    assert!(!snw.can_write_layer("page1/unknown", "page1", "did:key:user"));
302→    assert!(snw.should_sync_layer("page1/unknown", "page1", "did:key:user"));
303→}
