 14→/// Handle CreateDynamicLayer message
 15→///
 16→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 17→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
 18→/// **Returns**: Full layer name (bare, without page_id prefix)
 19→pub fn handle_create_dynamic_layer(
 20→    state: &mut ScribeState,
 21→    schema_key: &str,
 22→    layer_id: &str,
 23→) -> Result<String, String> {
 24→    let permit = state.our_permit.as_ref()
 25→        .ok_or_else(|| "No permit available".to_string())?;
 26→
 27→    // Validate schema exists in our permit's dynamic_layer_schemas
 28→    let schemas = permit.dynamic_layer_schemas();
 29→    let schema = schemas
 30→        .get(schema_key)
 31→        .cloned()
 32→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 33→
 34→    // Generate full layer path with our DID
 35→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 36→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 37→    let full_name = format!("{}/{}", state.page_id, bare_path);
 38→
 39→    // Check if layer already exists
 40→    if state.units.contains_key(&bare_path) {
 41→        info!(layer = %bare_path, "Dynamic layer already exists");
 42→        return Ok(full_name);
 43→    }
 44→
 45→    // Create the layer
 46→    info!(
 47→        page_id = %state.page_id,
 48→        schema = %schema_key,
 49→        layer = %bare_path,
 50→        "Creating dynamic layer"
 51→    );
 52→    let mut unit = LayerUnit::new_empty();
 53→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 54→    unit.is_dynamic = true;
 55→    state.units.insert(bare_path.clone(), unit);
 56→    state.track_new_sync_layer_in_meta(&bare_path);
 57→
 58→    // Add all connected subscribers to the new layer
 59→    if let Ok(subs) = state.subscribers.read() {
 60→        for ((did, _), info) in subs.iter() {
 61→            if let Some(unit) = state.units.get(&bare_path) {
 62→                let caps = super::Capabilities { read: true, write: true, sync: true };
 63→                unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
 64→                state.emit_layer_auth_capture(&bare_path, did, "subscriber_added_on_create");
 65→            }
 66→        }
 67→    }
 68→
 69→    // Set up observer for the new layer
 70→    loro_observer::setup_layer_observer(state, &bare_path);
 71→
 72→    issue_creator_layer_authority_permits(state, &full_name, &schema);
 73→
 74→    Ok(full_name)
 75→}
 76→
 77→fn issue_creator_layer_authority_permits(
 78→    state: &ScribeState,
 79→    full_layer_name: &str,
 80→    schema: &gurkha::DynamicLayerSchema,
 81→) {
 82→    let Some(ref issuer) = state.permit_issuer else { return; };
 83→
 84→    let mut targets: Vec<(String, Option<String>)> = Vec::new();
 85→    if let Ok(subs) = state.subscribers.read() {
 86→        for ((did, _device), info) in subs.iter() {
 87→            let role = info
 88→                .permit
 89→                .get_fact("role")
 90→                .and_then(|v| v.as_str())
 91→                .map(|r| r.to_string())
 92→                .or_else(|| {
 93→                    info.permit
 94→                        .get_fact("relationship")
 95→                        .and_then(|v| v.as_str())
 96→                        .map(|r| r.to_string())
 97→                });
 98→            targets.push((did.clone(), role));
 99→        }
100→    }
101→
102→    for (audience, role) in targets {
103→        let Some(config) = authority_config_from_template(schema, role.as_deref()) else {
104→            warn!(
105→                page_id = %state.page_id,
106→                layer = %full_layer_name,
107→                audience = %audience,
108→                role = role.as_deref().unwrap_or("unknown"),
109→                "Skipping layer authority issuance: no matching template config"
110→            );
111→            continue;
112→        };
113→
114→        match issuer.issue_layer_authority_permit(
115→            &audience,
116→            full_layer_name,
117→            config,
118→            None,
119→            1,
120→        ) {
121→            Ok((_token, _cid)) => {
122→                info!(
123→                    page_id = %state.page_id,
124→                    layer = %full_layer_name,
125→                    audience = %audience,
126→                    "Issued creator layer authority permit"
127→                );
128→            }
129→            Err(e) => {
130→                warn!(
131→                    page_id = %state.page_id,
132→                    layer = %full_layer_name,
133→                    audience = %audience,
134→                    error = %e,
135→                    "Failed to issue creator layer authority permit"
136→                );
137→            }
138→        }
139→    }
140→}
141→
142→fn authority_config_from_template(
143→    schema: &gurkha::DynamicLayerSchema,
144→    role: Option<&str>,
145→) -> Option<gurkha::LayerConfig> {
146→    let mut config = match schema.grant {
147→        gurkha::GrantType::Explicit => schema.permissions.clone(),
148→        gurkha::GrantType::Role => role.and_then(|r| schema.role_permissions.get(r).cloned()),
149→    }?;
150→
151→    if config.layer_type.is_none() && !schema.layer_type.is_empty() {
152→        config.layer_type = Some(schema.layer_type.clone());
153→    }
154→
155→    Some(config)
156→}
157→
158→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
159→///
160→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
161→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
162→///
163→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
164→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
165→    let parts: Vec<&str> = schema_key.split('/').collect();
166→    let mut result = Vec::new();
167→
168→    if parts.is_empty() {
169→        return format!("{}/{}", our_did, layer_id);
170→    }
171→
172→    // First segment: literal
173→    result.push(parts[0].to_string());
174→
175→    // Insert our DID as the second segment (namespace)
176→    result.push(our_did.to_string());
177→
178→    // Remaining segments: replace {id} with layer_id, keep literals
179→    for part in &parts[1..] {
180→        if *part == "{id}" {
181→            result.push(layer_id.to_string());
182→        } else {
183→            result.push(part.to_string());
184→        }
185→    }
186→
187→    result.join("/")
188→}
189→
190→/// Determine recipients and create layer permits for a new dynamic layer
191→///
192→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
193→/// **Returns**: Ready-to-send permits — courier just distributes them.
194→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
195→pub fn prepare_layer_permits(
196→    permit_issuer: &dyn PermitIssuer,
197→    page_id: &str,
198→    layer_name: &str,
199→    schema: &gurkha::DynamicLayerSchema,
200→    creator_did: &str,
201→    connected_peers: &[(String, String)],  // (did, role)
202→) -> Result<Vec<(String, String)>, String> {
203→    let mut permits = Vec::new();
204→
205→    match schema.grant {
206→        gurkha::GrantType::Role => {
207→            // Role-granted: all peers with matching roles get access
208→            for (did, role) in connected_peers {
209→                if let Some(perms) = schema.role_permissions.get(role) {
210→                    match permit_issuer.issue_layer_permit(did, layer_name, perms.clone(), None) {
211→                        Ok((token, _cid)) => {
212→                            info!(
213→                                page_id = %page_id,
214→                                layer = %layer_name,
215→                                recipient = %did,
216→                                role = %role,
217→                                "Issued role-based layer permit"
218→                            );
219→                            permits.push((did.clone(), token));
220→                        }
221→                        Err(e) => {
222→                            warn!(
223→                                page_id = %page_id,
224→                                layer = %layer_name,
225→                                recipient = %did,
226→                                error = %e,
227→                                "Failed to issue layer permit"
228→                            );
229→                        }
230→                    }
231→                }
232→            }
233→        }
234→        gurkha::GrantType::Explicit => {
235→            // Explicit-granted: authority-driven only (creator -> node permits).
236→            for (audience_did, _role) in connected_peers {
237→                let Some((config, intent_cid)) = authority_layer_config_and_intent(
238→                    permit_issuer,
239→                    audience_did,
240→                    layer_name,
241→                    page_id,
242→                ) else {
243→                    continue;
244→                };
245→
246→                match permit_issuer.issue_layer_permit(
247→                    audience_did,
248→                    layer_name,
249→                    config,
250→                    Some(&intent_cid),
251→                ) {
252→                    Ok((token, _cid)) => {
253→                        info!(
254→                            page_id = %page_id,
255→                            layer = %layer_name,
256→                            audience = %audience_did,
257→                            creator = %creator_did,
258→                            "Issued explicit layer permit from authority"
259→                        );
260→                        permits.push((audience_did.clone(), token));
261→                    }
262→                    Err(e) => {
263→                        warn!(
264→                            page_id = %page_id,
265→                            layer = %layer_name,
266→                            audience = %audience_did,
267→                            error = %e,
268→                            "Failed to issue explicit layer permit from authority"
269→                        );
270→                    }
271→                }
272→            }
273→        }
274→    }
275→
276→    Ok(permits)
277→}
278→
279→/// Find matching dynamic schema for a layer received from a peer
280→///
281→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
282→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
283→pub fn find_matching_dynamic_schema<'a>(
284→    permit: &'a gurkha::Permit,
285→    layer_name: &str,
286→    page_id: &str,
287→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
288→    let schemas = permit.dynamic_layer_schemas();
289→    if schemas.is_empty() {
290→        return None;
291→    }
292→
293→    // Strip page_id prefix to get bare layer path
294→    let page_prefix = format!("{}/", page_id);
295→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
296→
297→    let path_parts: Vec<&str> = bare_path.split('/').collect();
298→
299→    // Path must have at least 3 segments: prefix/did/id[/suffix]
300→    if path_parts.len() < 3 {
301→        return None;
302→    }
303→
304→    // Second segment should be a DID (the creator)
305→    let potential_creator = path_parts[1];
306→    if !potential_creator.starts_with("did:") {
307→        return None;
308→    }
309→
310→    // Try each schema pattern
311→    for (schema_key, schema) in schemas {
312→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
313→
314→        // Dynamic path has one extra segment (DID) compared to pattern
315→        if path_parts.len() != pattern_parts.len() + 1 {
316→            continue;
317→        }
318→
319→        // First segment must match literally
320→        if path_parts[0] != pattern_parts[0] {
321→            continue;
322→        }
323→
324→        // path[2..] must match pattern[1..] (with {id} as wildcard)
325→        let mut matched = true;
326→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
327→            if *pat_seg != "{id}" && path_seg != pat_seg {
328→                matched = false;
329→                break;
330→            }
331→        }
332→
333→        if matched {
334→            return Some((schema_key, schema, potential_creator.to_string()));
335→        }
336→    }
337→
338→    None
339→}
340→
341→/// Validate that a layer path created by a peer matches their DID (namespace security)
342→///
343→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
344→/// that the creator's DID is in the layer path (prevents namespace forgery).
345→///
346→/// **Returns**: true if the layer path contains the sender's DID
347→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
348→    let page_prefix = format!("{}/", page_id);
349→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
350→
351→    // The creator's DID must be the second segment in the path
352→    let parts: Vec<&str> = bare_path.split('/').collect();
353→    if parts.len() < 2 {
354→        return false;
355→    }
356→
357→    parts[1] == sender_did
358→}
359→
360→/// Handle AddLayerAccess message
361→///
362→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
363→/// **We do**: Validate capability, require authority permit, issue permit if peer is subscribed
364→pub async fn handle_add_layer_access(
365→    state: &ScribeState,
366→    layer_name: &str,
367→    did: &str,
368→) -> Result<(), String> {
369→    // 1. Check our permit has manage_layer_access capability
370→    let permit = state.our_permit.as_ref().ok_or_else(|| {
371→        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
372→        "No permit".to_string()
373→    })?;
374→    if !permit.can_manage_layer_access() {
375→        warn!(
376→            page_id = %state.page_id,
377→            layer = %layer_name,
378→            audience = %did,
379→            "AddLayerAccess rejected: missing manage_layer_access capability"
380→        );
381→        return Err("No manage_layer_access capability".into());
382→    }
383→
384→    // 2. Resolve schema/config and permit issuer
385→    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
386→        warn!(
387→            page_id = %state.page_id,
388→            layer = %layer_name,
389→            audience = %did,
390→            "AddLayerAccess rejected: no permit issuer (not node mode)"
391→        );
392→        "No permit issuer (not node mode)".to_string()
393→    })?;
394→    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
395→        .ok_or_else(|| {
396→            warn!(
397→                page_id = %state.page_id,
398→                layer = %layer_name,
399→                audience = %did,
400→                "AddLayerAccess rejected: layer does not match dynamic schema"
401→            );
402→            "Layer does not match any dynamic schema".to_string()
403→        })?;
404→    if schema.grant != gurkha::GrantType::Explicit {
405→        warn!(
406→            page_id = %state.page_id,
407→            layer = %layer_name,
408→            audience = %did,
409→            "AddLayerAccess rejected: schema grant is not explicit"
410→        );
411→        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
412→    }
413→
414→    let (config, intent_cid, source) = if let Some((cfg, cid)) = authority_layer_config_and_intent(
415→        issuer.as_ref(),
416→        did,
417→        layer_name,
418→        &state.page_id,
419→    ) {
420→        (cfg, Some(cid), "authority")
421→    } else {
422→        let cfg = schema
423→            .permissions
424→            .clone()
425→            .ok_or_else(|| "Explicit schema missing permissions and no authority permit present".to_string())?;
426→        warn!(
427→            page_id = %state.page_id,
428→            layer = %layer_name,
429→            audience = %did,
430→            "No layer authority permit found; issuing access from explicit schema permissions"
431→        );
432→        (cfg, None, "schema_permissions")
433→    };
434→
435→    // 3. Issue permit (stored by coordinator even if peer is offline)
436→    let mut new_permits = Vec::new();
437→    match issuer.issue_layer_permit(did, layer_name, config, intent_cid.as_deref()) {
438→        Ok((token, _cid)) => {
439→            info!(
440→                page_id = %state.page_id,
441→                layer = %layer_name,
442→                audience = %did,
443→                source = %source,
444→                "Issued layer permit via AddLayerAccess"
445→            );
446→            new_permits.push((did.to_string(), token));
447→        }
448→        Err(e) => {
449→            warn!(error = %e, "Failed to issue layer permit for AddLayerAccess");
450→        }
451→    }
452→
453→    // 4. Add DID as subscriber on the LayerUnit (if permit was issued)
454→    if let Some((recipient_did, _token)) = new_permits.first() {
455→        let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
456→        let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
457→            subs.iter()
458→                .find(|((d, _), _)| d == recipient_did)
459→                .map(|(_, info)| info.broadcast_tx.clone())
460→        });
461→        if let (Some(unit), Some(tx)) = (state.units.get(&bare_name), broadcast_tx) {
462→            let caps = super::Capabilities { read: true, write: true, sync: true };
463→            unit.add_subscriber(recipient_did.clone(), caps, tx);
464→            state.emit_layer_auth_capture(&bare_name, recipient_did, "subscriber_added_add_access");
465→        }
466→    }
467→
468→    // 5. Emit LayerAccessChanged for Coordinator to store/distribute permit
469→    if !new_permits.is_empty() {
470→        if let Some(ref sync_event_tx) = state.sync_event_tx {
471→            let event = crate::SyncEvent::LayerAccessChanged {
472→                page_id: state.page_id.clone(),
473→                layer_name: layer_name.to_string(),
474→                permits: new_permits,
475→            };
476→            state.emit_sync_event_capture(&event);
477→            if let Err(e) = sync_event_tx.send(event).await {
478→                warn!(error = %e, "Failed to emit LayerAccessChanged");
479→            }
480→        }
481→    }
482→
483→    Ok(())
484→}
485→
486→/// Handle RemoveLayerAccess message
487→///
488→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
489→/// **We do**: Validate capability, reject metadata-era revoke path
490→pub fn handle_remove_layer_access(
491→    state: &ScribeState,
492→    layer_name: &str,
493→    did: &str,
494→) -> Result<(), String> {
495→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
496→    if !permit.can_manage_layer_access() {
497→        return Err("No manage_layer_access capability".into());
498→    }
499→
500→    let _ = layer_name;
501→    let _ = did;
502→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
503→}
504→
505→fn authority_layer_config_and_intent(
506→    issuer: &dyn PermitIssuer,
507→    audience_did: &str,
508→    layer_name: &str,
509→    page_id: &str,
510→) -> Option<(gurkha::LayerConfig, String)> {
511→    let (_version, authority_token) = issuer
512→        .get_layer_authority_permit(audience_did, layer_name)
513→        .ok()
514→        .flatten()?;
515→
516→    let parsed = gurkha::Permit::from_token(&authority_token).ok()?;
517→    let config = if let Some(c) = parsed.layers().get(layer_name) {
518→        c.clone()
519→    } else {
520→        let bare = crate::state::normalize_layer_name(layer_name, page_id);
521→        parsed.layers().get(&bare)?.clone()
522→    };
523→
524→    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok()?;
525→    Some((config, intent_cid))
526→}
