    #[derive(Default)]
    struct RecordingPermitIssuer {
        issued: Arc<Mutex<Vec<(String, String, gurkha::LayerConfig)>>>,
    }

    impl PermitIssuer for RecordingPermitIssuer {
        fn issue_layer_permit(
