            // Explicit: authority-driven only (creator -> node permits).
            for audience_did in connected_peers {
                let Some((config, intent_cid)) = authority_layer_config_and_intent(
                    permit_issuer,
                    audience_did,
                    layer_name,
                    page_id,
                ) else {
                    continue;
                };

                match permit_issuer.issue_layer_permit(
                    audience_did,
                    layer_name,
                    config,
                    Some(&intent_cid),
                ) {
                    Ok((token, _cid)) => {
                        info!(
                            page_id = %page_id,
                            layer = %layer_name,
                            audience = %audience_did,
                            creator = %creator_did,
                            "Issued explicit layer permit from authority"
                        );
                        permits.push((audience_did.clone(), token));
                    }
                    Err(e) => {
                        warn!(
                            page_id = %page_id,
                            layer = %layer_name,
                            audience = %audience_did,
                            error = %e,
                            "Failed to issue explicit layer permit from authority"
                        );
                    }
                }
            }
        }
    }

    Ok(permits)
}

