#[instrument(skip(self, authority_permit, scribe, state), fields(page_id = %page_id, layer = %layer_name))]
async fn fanout_sync_meta_from_authority(
    &self,
    page_id: &str,
    layer_name: &str,
    authority_permit: &gurkha::Permit,
    scribe: &ractor::ActorRef<butler::ScribeMessage>,
    state: &PeerActorState<C>,
) {
    let our_did = match state.butler.user_info().await {
        Ok(info) => info.did,
        Err(e) => {
            warn!(error = %e, "Unable to resolve node DID for sync-meta fanout");
            return;
        }
    };

    let mut recipients = BTreeSet::new();
    match authority_permit.authorized_peers() {
        Ok(Some(explicit)) => {
            for did in explicit {
                if did != our_did {
                    recipients.insert(did);
                }
            }
        }
        Ok(None) => {
            // Authority permit doesn't carry dynamic_layer_schemas — look up
            // the node's own page permit which has them.
            let our_page_permit = match state.butler.pages().get(page_id) {
                Ok(Some(page)) => page.permit,
                _ => None,
            };
            let parsed_page_permit = our_page_permit.as_deref().and_then(|t| gurkha::Permit::from_token(t).ok());
            let schema = parsed_page_permit.as_ref().and_then(|p| {
                Self::authority_schema_for_layer(p, page_id, layer_name)
            });
            let Some(schema) = schema else {
                warn!(page_id = %page_id, layer = %layer_name, "No matching dynamic schema in page permit for role fanout");
                return;
            };

            let all_users = match state.butler.store().list_authorized_users_for_page(page_id) {
                Ok(users) => users,
                Err(e) => {
                    warn!(error = %e, "Failed to list authorized users for role fanout");
                    return;
                }
            };

            for user_did in all_users {
                if user_did == our_did {
                    continue;
                }

                let permit_token = match state.butler.store().get_user_page_permit(page_id, &user_did) {
                    Ok(Some(p)) => p,
                    _ => continue,
                };

                let parsed = match gurkha::Permit::from_token(&permit_token) {
                    Ok(p) => p,
                    Err(_) => continue,
                };

                let role = parsed
                    .get_fact("role")
                    .and_then(|v| v.as_str())
                    .or_else(|| parsed.get_fact("relationship").and_then(|v| v.as_str()));

                if let Some(role) = role {
                    if schema.role_permissions.contains_key(role) {
                        recipients.insert(user_did);
                    }
                }
            }
        }
        Err(e) => {
            warn!(error = %e, "Invalid authorized_peers in layer authority permit");
            return;
        }
    }

    info!(page_id = %page_id, layer = %layer_name, count = recipients.len(), "Fanout sync-meta to recipients");

    let bare_channel = layer_name
        .strip_prefix(&format!("{}/", page_id))
        .unwrap_or(layer_name);

