python3 -c "
import json
import sys

def transform_schema(obj):
    '''Recursively transform all DynamicLayerSchema objects'''
    if isinstance(obj, dict):
        new_obj = {}
        for key, value in obj.items():
            if key == 'dynamic_layer_schemas' and isinstance(value, dict):
                new_schemas = {}
                for schema_key, schema_val in value.items():
                    if isinstance(schema_val, dict):
                        new_schema = {}
                        for sk, sv in schema_val.items():
                            if sk == 'grant' and sv == 'role':
                                new_schema['grant'] = 'open'
                            elif sk == 'role_permissions':
                                # Flatten: take permissions from first role
                                if isinstance(sv, dict) and sv:
                                    first_role_perms = next(iter(sv.values()))
                                    new_schema['permissions'] = first_role_perms
                            else:
                                new_schema[sk] = sv
                        new_schemas[schema_key] = new_schema
                    else:
                        new_schemas[schema_key] = schema_val
                new_obj[key] = new_schemas
            else:
                new_obj[key] = transform_schema(value)
        return new_obj
    elif isinstance(obj, list):
        return [transform_schema(item) for item in obj]
    return obj

files = [
    'sample_apps/osvauld-demos/permit_template.json',
    'sample_apps/group-chat/permit_template.json',
    'sample_apps/my-shop/permit_template.json',
]

for filepath in files:
    with open(filepath, 'r') as f:
        data = json.load(f)

    transformed = transform_schema(data)

    with open(filepath, 'w') as f:
        json.dump(transformed, f, indent=4)
        f.write('\n')

    # Verify no role_permissions remain
    content = json.dumps(transformed)
    assert 'role_permissions' not in content, f'role_permissions still present in {filepath}'
    print(f'Transformed {filepath} - OK')
"

