///
/// **Context**: Determining role for Lua validation
/// **Checks**:
/// 1. Sync target (owner/viewer mode) -> our role's counterpart
/// 2. Stored permit (node mode) -> extract role from permit
/// 3. Default -> "peer"
#[instrument(skip(state), fields(page_id = %state.page_id))]
fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
    // If peer is our sync target, they are the "node" from our perspective
    if let Some(ref config) = state.sync_config {
        if let Some(ref sync_target) = config.sync_target {
            if sync_target == peer_did {
                return "node".to_string();
            }
        }
    }

    // Node mode: look up peer's stored permit and extract role via PermitContext
    if let Some(ref resolver) = state.peer_resolver {
        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
                .unwrap_or_else(|_| "peer".to_string());
            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
            return role;
        }
    }

    // Default role
    "peer".to_string()
}

