 19→async fn get_layer_json(peer: &Peer, page_id: &str, layer_name: &str) -> Result<Value> {
 20→    let scribe = peer.butler.open_page(page_id).await?;
 21→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 22→    scribe
 23→        .cast(ScribeMessage::GetLayerData {
 24→            layer_name: layer_name.to_string(),
 25→            reply: reply_tx,
 26→        })
 27→        .map_err(|e| anyhow::anyhow!("GetLayerData cast failed: {:?}", e))?;
 28→
 29→    reply_rx
 30→        .await
 31→        .map_err(|_| anyhow::anyhow!("GetLayerData channel closed"))?
 32→        .map_err(|e| anyhow::anyhow!("GetLayerData failed: {}", e))
 33→}
 34→
 35→/// Poll `get_layer_json` until a specific key appears in the map.
 36→async fn wait_for_layer_json_key(
 37→    peer: &Peer,
 38→    page_id: &str,
 39→    layer_name: &str,
 40→    key: &str,
 41→    timeout: Duration,
 42→) -> Result<Value> {
 43→    let deadline = tokio::time::Instant::now() + timeout;
 44→    loop {
 45→        if let Ok(json) = get_layer_json(peer, page_id, layer_name).await {
 46→            if let Some(val) = json.get(key) {
 47→                return Ok(val.clone());
 48→            }
 49→        }
 50→        if tokio::time::Instant::now() > deadline {
 51→            return Err(anyhow::anyhow!(
 52→                "Timeout waiting for key '{}' in layer '{}' on page '{}'",
 53→                key, layer_name, page_id
 54→            ));
 55→        }
 56→        tokio::time::sleep(Duration::from_millis(50)).await;
 57→    }
 58→}
