166→/// Determine recipients and create layer permits for a new dynamic layer
167→///
168→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
169→/// **Returns**: Ready-to-send permits — courier just distributes them.
170→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
171→pub fn prepare_layer_permits(
172→    permit_issuer: &dyn PermitIssuer,
173→    page_id: &str,
174→    layer_name: &str,
175→    schema: &gurkha::DynamicLayerSchema,
176→    creator_did: &str,
177→    connected_peers: &[String],
178→) -> Result<Vec<(String, String)>, String> {
179→    let mut permits = Vec::new();
180→
181→    match schema.grant {
182→        gurkha::GrantType::Open => {
183→            // Open: all connected peers get the same permissions
184→            let perms = schema.permissions.clone();
185→            for did in connected_peers {
186→                match permit_issuer.issue_layer_permit(did, layer_name, perms.clone(), None) {
187→                    Ok((token, _cid)) => {
188→                        info!(
189→                            page_id = %page_id,
190→                            layer = %layer_name,
191→                            recipient = %did,
192→                            "Issued open layer permit"
193→                        );
194→                        permits.push((did.clone(), token));
195→                    }
196→                    Err(e) => {
197→                        warn!(
198→                            page_id = %page_id,
199→                            layer = %layer_name,
200→                            recipient = %did,
201→                            error = %e,
202→                            "Failed to issue layer permit"
203→                        );
204→                    }
205→                }
206→            }
207→        }
208→        gurkha::GrantType::Explicit => {
209→            // Explicit: authority-driven only (creator -> node permits).
210→            for audience_did in connected_peers {
211→                let Some((config, intent_cid)) = authority_layer_config_and_intent(
212→                    permit_issuer,
213→                    audience_did,
214→                    layer_name,
215→                    page_id,
216→                ) else {
217→                    continue;
218→                };
219→
220→                match permit_issuer.issue_layer_permit(
221→                    audience_did,
222→                    layer_name,
223→                    config,
224→                    Some(&intent_cid),
225→                ) {
226→                    Ok((token, _cid)) => {
227→                        info!(
228→                            page_id = %page_id,
229→                            layer = %layer_name,
230→                            audience = %audience_did,
231→                            creator = %creator_did,
232→                            "Issued explicit layer permit from authority"
233→                        );
234→                        permits.push((audience_did.clone(), token));
235→                    }
236→                    Err(e) => {
237→                        warn!(
238→                            page_id = %page_id,
239→                            layer = %layer_name,
240→                            audience = %audience_did,
241→                            error = %e,
242→                            "Failed to issue explicit layer permit from authority"
243→                        );
244→                    }
245→                }
246→            }
247→        }
248→    }
249→
250→    Ok(permits)
251→}
