315→/// Validate that a layer path created by a peer matches their DID (namespace security)
316→///
317→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
318→/// that the creator's DID is in the layer path (prevents namespace forgery).
319→///
320→/// **Returns**: true if the layer path contains the sender's DID
321→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
322→    let page_prefix = format!("{}/", page_id);
323→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
324→
325→    // The creator's DID must be the second segment in the path
326→    let parts: Vec<&str> = bare_path.split('/').collect();
327→    if parts.len() < 2 {
328→        return false;
329→    }
330→
331→    parts[1] == sender_did
332→}
