457→/// Handle RemoveLayerAccess message
458→///
459→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
460→/// **We do**: Validate capability, reject metadata-era revoke path
461→pub fn handle_remove_layer_access(
462→    state: &ScribeState,
463→    layer_name: &str,
464→    did: &str,
465→) -> Result<(), String> {
466→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
467→    if !permit.can_manage_layer_access() {
468→        return Err("No manage_layer_access capability".into());
469→    }
470→
471→    let _ = layer_name;
472→    let _ = did;
473→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
474→}
475→
476→fn authority_layer_config_and_intent(
477→    issuer: &dyn PermitIssuer,
478→    audience_did: &str,
479→    layer_name: &str,
480→    page_id: &str,
481→) -> Option<(gurkha::LayerConfig, String)> {
482→    let (_version, authority_token) = issuer
483→        .get_layer_authority_permit(audience_did, layer_name)
484→        .ok()
485→        .flatten()?;
486→
487→    let parsed = gurkha::Permit::from_token(&authority_token).ok()?;
488→    let config = if let Some(c) = parsed.layers().get(layer_name) {
489→        c.clone()
490→    } else {
491→        let bare = crate::state::normalize_layer_name(layer_name, page_id);
492→        parsed.layers().get(&bare)?.clone()
493→    };
494→
495→    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok()?;
496→    Some((config, intent_cid))
497→}
