735→            gurkha::test_fixtures::handshake_viewer("page1", "did:key:alice"),
736→            "did:key:alice",
737→        );
738→        state
739→            .subscribers
740→            .write()
741→            .expect("subscriber lock poisoned")
742→            .insert(("did:key:alice".to_string(), "device1".to_string()), subscriber);
743→
744→        let schema = gurkha::DynamicLayerSchema {
745→            layer_type: "map".to_string(),
746→            grant: gurkha::GrantType::Open,
747→            permissions: gurkha::LayerConfig {
748→                sync: true,
749→                write: false,
750→                layer_type: None,
751→            },
752→        };
753→
754→        issue_creator_layer_authority_permits(
755→            &state,
756→            "page1/channels/did:key:owner/general/messages",
757→            &schema,
758→        );
759→
760→        let issued = issued.lock().expect("recording mutex poisoned");
761→        assert_eq!(issued.len(), 1, "exactly one authority permit should be issued");
762→        assert_eq!(issued[0].0, "did:key:alice");
763→        assert_eq!(issued[0].1, "page1/channels/did:key:owner/general/messages");
764→        assert_eq!(issued[0].2.sync, true);
765→        assert_eq!(issued[0].2.write, false, "must use schema permissions, not hardcoded write=true");
766→        assert_eq!(issued[0].2.layer_type.as_deref(), Some("map"));
767→    }
768→}
