  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→use std::collections::BTreeSet;
 20→
 21→use crate::message::*;
 22→use transport::Connection;
 23→
 24→use super::super::guards::require_auth;
 25→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 26→
 27→impl<C: Connection> PeerActor<C> {
 28→
 29→    fn is_sync_meta_layer(page_id: &str, layer_name: &str) -> bool {
 30→        layer_name.starts_with("__sync_meta/")
 31→            || layer_name.starts_with(&format!("{}/__sync_meta/", page_id))
 32→    }
 33→
 34→    #[instrument(skip(self, authority_permit, scribe, state), fields(page_id = %page_id, layer = %layer_name))]
 35→    async fn fanout_sync_meta_from_authority(
 36→        &self,
 37→        page_id: &str,
 38→        layer_name: &str,
 39→        authority_permit: &gurkha::Permit,
 40→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
 41→        state: &PeerActorState<C>,
 42→    ) {
 43→        let our_did = match state.butler.user_info().await {
 44→            Ok(info) => info.did,
 45→            Err(e) => {
 46→                warn!(error = %e, "Unable to resolve node DID for sync-meta fanout");
 47→                return;
 48→            }
 49→        };
 50→
 51→        let mut recipients = BTreeSet::new();
 52→        match authority_permit.authorized_peers() {
 53→            Ok(Some(explicit)) => {
 54→                for did in explicit {
 55→                    if did != our_did {
 56→                        recipients.insert(did);
 57→                    }
 58→                }
 59→            }
 60→            Ok(None) => {
 61→                // Open distribution: all peers with page access are recipients.
 62→                let all_users = match state.butler.store().list_authorized_users_for_page(page_id) {
 63→                    Ok(users) => users,
 64→                    Err(e) => {
 65→                        warn!(error = %e, "Failed to list authorized users for open fanout");
 66→                        return;
 67→                    }
 68→                };
 69→
 70→                for user_did in all_users {
 71→                    if user_did != our_did {
 72→                        recipients.insert(user_did);
 73→                    }
 74→                }
 75→            }
 76→            Err(e) => {
 77→                warn!(error = %e, "Invalid authorized_peers in layer authority permit");
 78→                return;
 79→            }
 80→        }
 81→
 82→        info!(page_id = %page_id, layer = %layer_name, count = recipients.len(), "Fanout sync-meta to recipients");
 83→
 84→        let bare_channel = layer_name
 85→            .strip_prefix(&format!("{}/", page_id))
 86→            .unwrap_or(layer_name);
 87→
 88→        for did in recipients {
 89→            let sync_meta_layer = format!("__sync_meta/{}", did);
 90→            let sync_meta_key = bare_channel.to_string();
 91→            info!(page_id = %page_id, target = %did, sync_meta_layer = %sync_meta_layer, key = %sync_meta_key, "Writing sync-meta entry for recipient");
 92→            if let Err(e) = scribe.cast(butler::ScribeMessage::MapInsert {
 93→                layer_name: sync_meta_layer,
 94→                path: String::new(),
 95→                key: sync_meta_key.clone(),
 96→                value: serde_json::json!({"synced": false, "version": 1}),
 97→            }) {
 98→                warn!(page_id = %page_id, layer = %layer_name, target = %did, error = %e, "Failed to write recipient sync-meta entry");
 99→            }
100→
101→            // Authorize recipient on the channel layer so Scribe broadcasts reach them
102→            scribe.cast(butler::ScribeMessage::AuthorizeLayerSubscriber {
103→                layer_name: bare_channel.to_string(),
104→                subscriber_did: did.clone(),
105→            }).ok();
106→            info!(page_id = %page_id, target = %did, layer = %bare_channel, "Authorized recipient on channel layer for broadcast");
107→        }
108→    }
109→
110→    #[instrument(skip(self, state, scribe), fields(page_id = %page_id, sync_meta_layer = %sync_meta_layer))]
111→    async fn request_missing_layers_from_sync_meta(
112→        &self,
113→        page_id: &str,
114→        sync_meta_layer: &str,
115→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
116→        state: &mut PeerActorState<C>,
117→    ) {
118→        let normalized_sync_meta_layer = sync_meta_layer
119→            .strip_prefix(&format!("{}/", page_id))
120→            .unwrap_or(sync_meta_layer)
121→            .to_string();
122→
123→        let (data_tx, data_rx) = tokio::sync::oneshot::channel();
124→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetLayerData {
125→            layer_name: normalized_sync_meta_layer,
126→            reply: data_tx,
127→        }) {
128→            warn!(error = %e, "Failed to read sync-meta layer for request planning");
129→            return;
130→        }
131→
132→        let sync_meta_json = match data_rx.await {
133→            Ok(Ok(v)) => v,
134→            Ok(Err(e)) => {
135→                warn!(error = %e, "GetLayerData failed for sync-meta layer");
136→                return;
137→            }
138→            Err(_) => {
139→                warn!("GetLayerData reply channel closed for sync-meta layer");
140→                return;
141→            }
142→        };
143→
144→        let Some(entries) = sync_meta_json.as_object() else {
145→            warn!("sync-meta layer content is not a map object");
146→            return;
147→        };
148→
149→        for (layer_name, _entry) in entries {
150→            let normalized_layer_name = layer_name
151→                .strip_prefix(&format!("{}/", page_id))
152→                .unwrap_or(layer_name)
153→                .to_string();
154→
155→            if normalized_layer_name.starts_with("__sync_meta/") {
156→                continue;
157→            }
158→
159→            let (exists_tx, exists_rx) = tokio::sync::oneshot::channel();
160→            if let Err(e) = scribe.cast(butler::ScribeMessage::LayerExists {
161→                layer_name: normalized_layer_name.clone(),
162→                reply: exists_tx,
163→            }) {
164→                warn!(layer = %normalized_layer_name, error = %e, "Failed to check layer existence");
165→                continue;
166→            }
167→
168→            let exists = match exists_rx.await {
169→                Ok(v) => v,
170→                Err(_) => {
171→                    warn!(layer = %normalized_layer_name, "LayerExists reply channel closed");
172→                    continue;
173→                }
174→            };
175→
176→            if exists {
177→                continue;
178→            }
179→
180→            info!(page_id = %page_id, layer = %normalized_layer_name, "Requesting missing layer via SyncReset after sync-meta discovery");
181→            let msg = Message::SyncReset(SyncResetMsg {
182→                page_id: page_id.to_string(),
183→                layer_name: normalized_layer_name,
184→            });
185→            self.send_message(&msg, state).await;
186→        }
187→    }
188→
189→    /// Handle incoming SyncOffer from peer (Step 1)
190→    ///
191→    /// **Context**: Peer has a layer update with their state vector
192→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
193→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
194→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
195→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
196→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public, authority_permit), fields(page_id = %page_id, layer_name = %layer_name))]
197→    pub(in crate::peer_actor) async fn on_sync_offer(
198→        &self,
199→        myself: ractor::ActorRef<super::super::PeerMessage>,
200→        page_id: &str,
201→        layer_name: &str,
202→        data: &[u8],
203→        their_state_vector: &[u8],
204→        ephemeral_public: &[u8; 32],
205→        authority_permit: Option<&str>,
206→        state: &mut PeerActorState<C>,
207→    ) {
208→        let (peer_did, _) = match require_auth(&state.state) {
209→            Ok(info) => (info.0.to_string(), info.1.to_string()),
210→            Err(_) => {
211→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
212→                return;
213→            }
214→        };
215→
216→        let peer_device_id = self.node_id.to_string();
217→
218→        debug!(
219→            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
220→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
221→        );
222→
223→        // Open page early so bundled authority fanout and apply share one Scribe handle.
224→        let scribe = match state.butler.open_page(page_id).await {
225→            Ok(s) => s,
226→            Err(e) => {
227→                error!("Failed to open page {}: {}", page_id, e);
228→                return;
229→            }
230→        };
231→
232→        if let Some(permit) = authority_permit {
233→            match gurkha::Permit::from_token(permit) {
234→                Ok(parsed) => {
235→                    if parsed.token_type() == Some("layer_authority") {
236→                        let audience = parsed.parsed().audience().to_string();
237→                        let version = parsed
238→                            .get_fact("version")
239→                            .and_then(|v| v.as_u64())
240→                            .unwrap_or(0);
241→                        let full_layer_name = if layer_name.starts_with(&format!("{}/", page_id)) {
242→                            layer_name.to_string()
243→                        } else {
244→                            format!("{}/{}", page_id, layer_name)
245→                        };
246→                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
247→                            page_id,
248→                            &full_layer_name,
249→                            &audience,
250→                            version,
251→                            permit,
252→                        ) {
253→                            warn!(
254→                                page_id = %page_id,
255→                                layer = %full_layer_name,
256→                                audience = %audience,
257→                                error = %e,
258→                                "Failed to store bundled layer authority permit"
259→                            );
260→                        }
261→
262→                        if state.mode == crate::CourierMode::Node {
263→                            self
264→                                .fanout_sync_meta_from_authority(
265→                                    page_id,
266→                                    &full_layer_name,
267→                                    &parsed,
268→                                    &scribe,
269→                                    state,
270→                                )
271→                                .await;
272→                        }
273→                    }
274→                }
275→                Err(e) => {
276→                    warn!(page_id = %page_id, layer = %layer_name, error = %e, "Invalid bundled authority permit in SyncOffer");
277→                }
278→            }
279→        }
280→
281→        // Decrypt transit-encrypted update using ECDH
282→        let our_secret = match state.butler.encryption_key().await {
283→            Ok(key) => key,
284→            Err(e) => {
285→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
286→                return;
287→            }
288→        };
289→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
290→            Ok(data) => data,
291→            Err(e) => {
292→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
293→                return;
294→            }
295→        };
296→
297→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
298→        // For Node mode: Ensures can_write() can check viewer's write permissions
299→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
300→        if !state.page_subscriptions.contains_key(page_id) {
301→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
302→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
303→        }
304→
305→        // Apply the update with result feedback
306→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
307→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
308→            layer_name: layer_name.to_string(),
309→            update: decrypted_data,
310→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
311→            permit: None,
312→            reply: reply_tx,
313→        }) {
314→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
315→            return;
316→        }
317→
318→        // Wait for apply result - only send SyncAccept if successful
319→        match reply_rx.await {
320→            Ok(Ok(())) => {
321→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
322→
323→                if Self::is_sync_meta_layer(page_id, layer_name) {
324→                    self
325→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
326→                        .await;
327→                }
328→            }
329→            Ok(Err(e)) => {
330→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
331→                // DO NOT send SyncAccept - this stops the infinite retry loop
332→                return;
333→            }
334→            Err(_) => {
335→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
336→                return;
337→            }
338→        }
339→
340→        // Get our state vector after applying
341→        let (tx, rx) = tokio::sync::oneshot::channel();
342→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
343→            layer_name: layer_name.to_string(),
344→            reply: tx.into(),
345→        }) {
346→            error!("Failed to request state vector from Scribe: {}", e);
347→            return;
348→        }
349→
350→        let our_state_vector = match rx.await {
351→            Ok(Ok(vector)) => vector,
352→            Ok(Err(e)) => {
353→                error!("Scribe returned error getting state vector: {}", e);
354→                return;
355→            }
356→            Err(_) => {
357→                error!("Scribe dropped state vector reply channel");
358→                return;
359→            }
360→        };
361→
362→        // Send SyncAccept with our state vector
363→        let msg = Message::SyncAccept(SyncAcceptMsg {
364→            page_id: page_id.to_string(),
365→            layer_name: layer_name.to_string(),
366→            state_vector: our_state_vector.clone(),
367→        });
368→
369→        self.send_message(&msg, state).await;
370→        debug!(
371→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
372→            page_id, layer_name, peer_did, our_state_vector.len()
373→        );
374→    }
375→
376→    /// Handle incoming SyncAccept from peer (Step 2)
377→    ///
378→    /// **Context**: Peer applied our update and reports their state vector
379→    /// **Peer sends**: SyncAccept with their state vector after applying
380→    /// **We compare**: Their vector with our current vector
381→    /// **If match**: Send SyncAck (sync complete)
382→    /// **If diverged**: Send new SyncOffer with full diff from their vector (resync)
383→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
384→    pub(in crate::peer_actor) async fn on_sync_accept(
385→        &self,
386→        page_id: &str,
387→        layer_name: &str,
388→        their_state_vector: &[u8],
389→        state: &mut PeerActorState<C>,
390→    ) {
391→        let (peer_did, _) = match require_auth(&state.state) {
392→            Ok(info) => (info.0.to_string(), info.1.to_string()),
393→            Err(_) => {
394→                warn!("SyncAccept from unauthenticated peer: {}", self.node_id);
395→                return;
396→            }
397→        };
398→
399→        debug!(
400→            "SyncAccept: page={} layer={} from {} (their vector {} bytes)",
401→            page_id, layer_name, peer_did, their_state_vector.len()
402→        );
403→
404→        // Get pending sync context (may not exist for fire-and-forget broadcasts)
405→        let key = (page_id.to_string(), layer_name.to_string());
406→        let pending = state.pending_sync_offers.remove(&key);
407→
408→        // Get our current state vector from Scribe
409→        let scribe = match state.butler.open_page(page_id).await {
410→            Ok(s) => s,
411→            Err(e) => {
412→                error!("Failed to open page {}: {}", page_id, e);
413→                return;
414→            }
415→        };
416→
417→        let (tx, rx) = tokio::sync::oneshot::channel();
418→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
419→            layer_name: layer_name.to_string(),
420→            reply: tx.into(),
421→        }) {
422→            error!("Failed to request state vector from Scribe: {}", e);
423→            return;
424→        }
425→
426→        let our_current_vector = match rx.await {
427→            Ok(Ok(vector)) => vector,
428→            Ok(Err(e)) => {
429→                error!("Scribe returned error getting state vector: {}", e);
430→                return;
431→            }
432→            Err(_) => {
433→                error!("Scribe dropped state vector reply channel");
434→                return;
435→            }
436→        };
437→
438→        // Handle based on whether we have a pending offer
439→        match pending {
440→            None => {
441→                // Fire-and-forget broadcast: No pending offer tracked.
442→                // Just update peer vector cache and send SyncAck. Trust CRDT to converge.
443→                debug!(
444→                    "SyncAccept: no pending offer (fire-and-forget) for page={} layer={} - sending SyncAck",
445→                    page_id, layer_name
446→                );
447→
448→                let msg = Message::SyncAck(SyncAckMsg {
449→                    page_id: page_id.to_string(),
450→                    layer_name: layer_name.to_string(),
451→                    state_vector: our_current_vector,
452→                });
453→                self.send_message(&msg, state).await;
454→
455→                // Update Scribe's in-memory vector cache (persistence via periodic flush)
456→                let peer_device_id = self.node_id.to_string();
457→                if let Some(subscription) = state.page_subscriptions.get(page_id) {
458→                    let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
459→                        user_did: peer_did,
460→                        device_id: peer_device_id,
461→                        layer_name: layer_name.to_string(),
462→                        state_vector: their_state_vector.to_vec(),
463→                    });
464→                }
465→            }
466→            Some(offer) => {
467→                // Tracked sync (initial sync / reconciliation): Compare vectors
468→                trace!(
469→                    "SyncAccept comparison: their_vector={} bytes, offered_vector={} bytes, current_vector={} bytes",
470→                    their_state_vector.len(),
471→                    offer.our_state_vector.len(),
472→                    our_current_vector.len()
473→                );
474→
475→                if their_state_vector == offer.our_state_vector.as_slice() {
476→                    // In sync! Send SyncAck
477→                    trace!(
478→                        "SyncAccept: vectors match for page={} layer={} - sending SyncAck",
479→                        page_id, layer_name
480→                    );
481→
482→                    let msg = Message::SyncAck(SyncAckMsg {
483→                        page_id: page_id.to_string(),
484→                        layer_name: layer_name.to_string(),
485→                        state_vector: our_current_vector,
486→                    });
487→                    self.send_message(&msg, state).await;
488→
489→                    // Update Scribe's in-memory vector cache (persistence via periodic flush)
490→                    let peer_device_id = self.node_id.to_string();
491→                    if let Some(subscription) = state.page_subscriptions.get(page_id) {
492→                        let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
493→                            user_did: peer_did,
494→                            device_id: peer_device_id,
495→                            layer_name: layer_name.to_string(),
496→                            state_vector: their_state_vector.to_vec(),
497→                        });
498→                    }
499→                } else {
500→                    // Diverged! Check if we should resync or fall back to SyncReset
501→                    let new_attempts = offer.resync_attempts + 1;
502→
503→                    if new_attempts > MAX_RESYNC_ATTEMPTS {
504→                        // Max resyncs exceeded - fall back to SyncReset (request full snapshot)
505→                        warn!(
506→                            "SyncAccept: max resyncs ({}) exceeded for page={} layer={} - sending SyncReset",
507→                            MAX_RESYNC_ATTEMPTS, page_id, layer_name
508→                        );
509→
510→                        let msg = Message::SyncReset(SyncResetMsg {
511→                            page_id: page_id.to_string(),
512→                            layer_name: layer_name.to_string(),
513→                        });
514→                        self.send_message(&msg, state).await;
515→                        return;
516→                    }
517→
518→                    // Still have retries - send resync SyncOffer with full diff from their vector
519→                    info!(
520→                        "SyncAccept: vectors DIVERGED for page={} layer={} - sending resync SyncOffer (attempt {}/{})",
521→                        page_id, layer_name, new_attempts, MAX_RESYNC_ATTEMPTS
522→                    );
523→
524→                    // Get diff from their state vector
525→                    let (tx, rx) = tokio::sync::oneshot::channel();
526→                    if let Err(e) = scribe.cast(butler::ScribeMessage::GetUpdatesSince {
527→                        layer_name: layer_name.to_string(),
528→                        state_vector: their_state_vector.to_vec(),
529→                        reply: tx,
530→                    }) {
531→                        error!("Failed to request updates from Scribe: {}", e);
532→                        return;
533→                    }
534→
535→                    let diff = match rx.await {
536→                        Ok(Ok(d)) => d,
537→                        Ok(Err(e)) => {
538→                            error!("Scribe returned error getting updates: {}", e);
539→                            return;
540→                        }
541→                        Err(_) => {
542→                            error!("Scribe dropped updates reply channel");
543→                            return;
544→                        }
545→                    };
546→
547→                    // Encrypt and send new SyncOffer
548→                    let peer_encryption_key = match state.peer_encryption_key {
549→                        Some(key) => key,
550→                        None => {
551→                            warn!("Cannot send resync SyncOffer: peer encryption key not set");
552→                            return;
553→                        }
554→                    };
555→
556→                    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
557→                        &peer_encryption_key,
558→                        &diff,
559→                    ) {
560→                        Ok(result) => result,
561→                        Err(e) => {
562→                            error!("Failed to encrypt resync data: {}", e);
563→                            return;
564→                        }
565→                    };
566→
567→                    // Track this new pending sync with incremented attempt counter
568→                    state.pending_sync_offers.insert(
569→                        key,
570→                        super::super::PendingSyncOffer {
571→                            our_state_vector: our_current_vector.clone(),
572→                            permit: String::new(),
573→                            resync_attempts: new_attempts,
574→                        },
575→                    );
576→
577→                    let layer_name_owned = layer_name.to_string();
578→                    let msg = Message::SyncOffer(SyncOfferMsg {
579→                        page_id: page_id.to_string(),
580→                        layer_type: LayerType::from_layer_name(&layer_name_owned),
581→                        layer_name: layer_name_owned,
582→                        data: encrypted_data,
583→                        state_vector: our_current_vector,
584→                        ephemeral_public,
585→                        authority_permit: None,
586→                    });
587→                    self.send_message(&msg, state).await;
588→                }
589→            }
590→        }
591→    }
592→
593→    /// Handle incoming SyncAck from peer (Step 3)
594→    ///
595→    /// **Context**: Peer confirms sync complete after comparing vectors
596→    /// **Peer sends**: SyncAck with their final state vector
597→    /// **We do**: Update cached peer vector, log sync complete
598→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
599→    pub(in crate::peer_actor) async fn on_sync_ack(
600→        &self,
601→        page_id: &str,
602→        layer_name: &str,
603→        their_state_vector: &[u8],
604→        state: &mut PeerActorState<C>,
605→    ) {
606→        let (peer_did, _) = match require_auth(&state.state) {
607→            Ok(info) => (info.0.to_string(), info.1.to_string()),
608→            Err(_) => {
609→                warn!("SyncAck from unauthenticated peer: {}", self.node_id);
610→                return;
611→            }
612→        };
613→
614→        debug!(
615→            "SyncAck: page={} layer={} from {} - sync complete",
616→            page_id, layer_name, peer_did
617→        );
618→
619→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
620→        let peer_device_id = self.node_id.to_string();
621→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
622→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
623→                user_did: peer_did.clone(),
624→                device_id: peer_device_id.clone(),
625→                layer_name: layer_name.to_string(),
626→                state_vector: their_state_vector.to_vec(),
627→            });
628→        }
629→
630→        // Clean up any pending sync for this page/layer (shouldn't exist but be safe)
631→        let key = (page_id.to_string(), layer_name.to_string());
632→        state.pending_sync_offers.remove(&key);
633→
634→        // Check if this is an assets layer sync - trigger asset fetch for missing blobs
635→        if layer_name == "assets" || layer_name.ends_with("/assets") {
636→            self.trigger_asset_sync_after_layer_sync(page_id, layer_name, state).await;
637→        }
638→    }
639→
640→    /// Handle incoming SyncReset from peer (fallback after max resyncs)
641→    ///
642→    /// **Context**: Peer exceeded MAX_RESYNC_ATTEMPTS OR explicitly needs layer snapshot.
643→    /// **Both modes**: Respond with SyncSnapshot when layer exists locally.
644→    #[instrument(skip(self, state), fields(page_id = %page_id, layer_name = %layer_name))]
645→    pub(in crate::peer_actor) async fn on_sync_reset(
646→        &self,
647→        page_id: &str,
648→        layer_name: &str,
649→        state: &mut PeerActorState<C>,
650→    ) {
651→        let peer_did = match require_auth(&state.state) {
652→            Ok((did, _)) => did.to_string(),
653→            Err(_) => {
654→                warn!("SyncReset from unauthenticated peer: {}", self.node_id);
655→                return;
656→            }
657→        };
658→
659→        info!(
660→            "SyncReset: page={} layer={} from {} - sending full snapshot",
661→            page_id, layer_name, peer_did
662→        );
663→
664→        // Get Scribe and export full snapshot
665→        let scribe = match state.butler.open_page(page_id).await {
666→            Ok(s) => s,
667→            Err(e) => {
668→                error!("Failed to open page {} for SyncReset: {}", page_id, e);
669→                return;
670→            }
671→        };
672→
673→        // Get full snapshot
674→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
675→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
676→            layer_name: layer_name.to_string(),
677→            reply: snapshot_tx,
678→        }) {
679→            error!("Failed to request snapshot from Scribe: {}", e);
680→            return;
681→        }
682→
683→        let snapshot = match snapshot_rx.await {
684→            Ok(Some(data)) => data,
685→            Ok(None) => {
686→                warn!("Layer {} not found in Scribe for SyncReset", layer_name);
687→                return;
688→            }
689→            Err(_) => {
690→                error!("Scribe dropped snapshot reply channel");
691→                return;
692→            }
693→        };
694→
695→        // Get state vector
696→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
697→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
698→            layer_name: layer_name.to_string(),
699→            reply: vector_tx.into(),
700→        }) {
701→            error!("Failed to request state vector from Scribe: {}", e);
702→            return;
703→        }
704→
705→        let state_vector = match vector_rx.await {
706→            Ok(Ok(v)) => v,
707→            Ok(Err(e)) => {
708→                error!("Scribe returned error getting state vector: {}", e);
709→                return;
710→            }
711→            Err(_) => {
712→                error!("Scribe dropped state vector reply channel");
713→                return;
714→            }
715→        };
716→
717→        // Encrypt snapshot for transfer
718→        let peer_encryption_key = match state.peer_encryption_key {
719→            Some(key) => key,
720→            None => {
721→                warn!("Cannot send SyncSnapshot: peer encryption key not set");
722→                return;
723→            }
724→        };
725→
726→        let (ephemeral_public, encrypted_snapshot) = match herald::encrypt_for_transfer(
727→            &peer_encryption_key,
728→            &snapshot,
729→        ) {
730→            Ok(result) => result,
731→            Err(e) => {
732→                error!("Failed to encrypt snapshot: {}", e);
733→                return;
734→            }
735→        };
736→
737→        // Send SyncSnapshot
738→        let layer_name_owned = layer_name.to_string();
739→        let msg = Message::SyncSnapshot(SyncSnapshotMsg {
740→            page_id: page_id.to_string(),
741→            layer_type: LayerType::from_layer_name(&layer_name_owned),
742→            layer_name: layer_name_owned,
743→            snapshot: encrypted_snapshot,
744→            state_vector,
745→            ephemeral_public,
746→        });
747→        self.send_message(&msg, state).await;
748→
749→        info!(
750→            "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
751→            page_id, layer_name, peer_did, snapshot.len()
752→        );
753→    }
754→
755→    /// Handle incoming SyncSnapshot from peer (response to SyncReset)
756→    ///
757→    /// **Context**: Peer responded to our SyncReset with a full snapshot.
758→    /// **Both modes**: Replace local layer with received state.
759→    #[instrument(skip(self, state, snapshot, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
760→    pub(in crate::peer_actor) async fn on_sync_snapshot(
761→        &self,
762→        page_id: &str,
763→        layer_name: &str,
764→        snapshot: &[u8],
765→        their_state_vector: &[u8],
766→        ephemeral_public: &[u8; 32],
767→        state: &mut PeerActorState<C>,
768→    ) {
769→        let peer_did = match require_auth(&state.state) {
770→            Ok((did, _)) => did.to_string(),
771→            Err(_) => {
772→                warn!("SyncSnapshot from unauthenticated peer: {}", self.node_id);
773→                return;
774→            }
775→        };
776→
777→        info!(
778→            "SyncSnapshot: page={} layer={} from {} ({} bytes) - replacing local state",
779→            page_id, layer_name, peer_did, snapshot.len()
780→        );
781→
782→        // Decrypt snapshot
783→        let our_secret = match state.butler.encryption_key().await {
784→            Ok(key) => key,
785→            Err(e) => {
786→                error!("Failed to get encryption key for SyncSnapshot decryption: {}", e);
787→                return;
788→            }
789→        };
790→
791→        let decrypted_snapshot = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, snapshot) {
792→            Ok(data) => data,
793→            Err(e) => {
794→                error!("Failed to decrypt SyncSnapshot from {}: {}", peer_did, e);
795→                return;
796→            }
797→        };
798→
799→        // Get Scribe and replace layer
800→        let scribe = match state.butler.open_page(page_id).await {
801→            Ok(s) => s,
802→            Err(e) => {
803→                error!("Failed to open page {} for SyncSnapshot: {}", page_id, e);
804→                return;
805→            }
806→        };
807→
808→        // Replace layer with snapshot
809→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
810→        if let Err(e) = scribe.cast(butler::ScribeMessage::ReplaceLayer {
811→            layer_name: layer_name.to_string(),
812→            snapshot: decrypted_snapshot,
813→            reply: reply_tx,
814→        }) {
815→            error!("Failed to send ReplaceLayer to Scribe: {}", e);
816→            return;
817→        }
818→
819→        match reply_rx.await {
820→            Ok(Ok(())) => {
821→                info!(
822→                    "SyncSnapshot applied: page={} layer={} - sync recovery complete",
823→                    page_id, layer_name
824→                );
825→
826→                if Self::is_sync_meta_layer(page_id, layer_name) {
827→                    self
828→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
829→                        .await;
830→                }
831→            }
832→            Ok(Err(e)) => {
833→                error!("ReplaceLayer failed for page={} layer={}: {}", page_id, layer_name, e);
834→                return;
835→            }
836→            Err(_) => {
837→                error!("Scribe dropped ReplaceLayer reply channel");
838→                return;
839→            }
840→        }
841→
842→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
843→        let peer_device_id = self.node_id.to_string();
844→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
845→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
846→                user_did: peer_did.clone(),
847→                device_id: peer_device_id,
848→                layer_name: layer_name.to_string(),
849→                state_vector: their_state_vector.to_vec(),
850→            });
851→        }
852→
853→        // Clean up any pending sync
854→        let key = (page_id.to_string(), layer_name.to_string());
855→        state.pending_sync_offers.remove(&key);
856→    }
857→}
