447→/// Detect if a newly created layer matches a dynamic schema and emit permits
448→///
449→/// **Context**: Node receives a new layer from peer via sync. If it matches a dynamic
450→/// schema, prepare layer permits and emit NewDynamicLayer for distribution.
451→/// **Offline-first**: Discovery happens via `__sync_meta/` — the creator already wrote
452→/// their sync_meta entry, and the node fans out `__sync_meta/{viewer_did}` entries
453→/// via `fanout_sync_meta_from_authority()` in Courier when the authority permit is present.
454→/// No direct broadcast authorization — same path for online and offline peers.
455→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
456→async fn emit_dynamic_layer_permits(
457→    state: &ScribeState,
458→    layer_name: &str,
459→    from_peer: &(String, String),
460→) {
461→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
462→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
463→    let Some(ref our_permit) = state.our_permit else { return; };
464→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
465→
466→    // Check if layer matches a dynamic schema
467→    let Some((schema_key, schema, creator_did)) =
468→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
469→
470→    // Validate creator namespace: sender's DID must match DID in path
471→    if from_peer.0 != creator_did {
472→        warn!(
473→            layer = %layer_name,
474→            sender = %from_peer.0,
475→            creator = %creator_did,
476→            "Creator namespace mismatch — sender DID doesn't match path DID"
477→        );
478→        return;
479→    }
480→
481→    // Collect connected peer DIDs
482→    let connected_peers = collect_connected_peer_dids(state);
483→
484→    // Prepare layer permits
485→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
486→    match prepare_layer_permits(
487→        permit_issuer.as_ref(),
488→        &state.page_id,
489→        &full_layer_name,
490→        schema,
491→        &creator_did,
492→        &connected_peers,
493→    ) {
494→        Ok(permits) if !permits.is_empty() => {
495→            info!(
496→                layer = %layer_name,
497→                schema = %schema_key,
498→                creator = %creator_did,
499→                permit_count = permits.len(),
500→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
501→            );
502→
503→            // Add each permit recipient as subscriber on the LayerUnit
504→            if let Ok(subs) = state.subscribers.read() {
505→                for (did, _token) in &permits {
506→                    let broadcast_tx = subs.iter()
507→                        .find(|((d, _), _)| d == did)
508→                        .map(|(_, info)| info.broadcast_tx.clone());
509→                    if let (Some(unit), Some(tx)) = (state.units.get(layer_name), broadcast_tx) {
510→                        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
511→                        unit.add_subscriber(did.clone(), caps, tx);
512→                        state.emit_layer_auth_capture(layer_name, did, "subscriber_added_dynamic_permit");
513→                    }
514→                }
515→            }
516→
517→            let event = SyncEvent::NewDynamicLayer {
518→                page_id: state.page_id.clone(),
519→                layer_name: full_layer_name,
520→                permits,
521→            };
522→
523→            state.emit_sync_event_capture(&event);
524→            if let Err(e) = sync_event_tx.send(event).await {
525→                error!(error = %e, "Failed to emit NewDynamicLayer event");
526→            }
527→        }
528→        Ok(_) => {
529→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
530→        }
531→        Err(e) => {
532→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
533→        }
534→    }
535→}
