537→/// Collect connected peer DIDs from subscriber info
538→///
539→/// **Context**: Node needs DID list for prepare_layer_permits
540→fn collect_connected_peer_dids(state: &ScribeState) -> Vec<String> {
541→    let mut peers = Vec::new();
542→
543→    if let Ok(subs) = state.subscribers.read() {
544→        for ((did, _device_id), _info) in subs.iter() {
545→            // Avoid duplicates (same DID, different devices)
546→            if !peers.contains(did) {
547→                peers.push(did.clone());
548→            }
549→        }
550→    }
551→
552→    peers
553→}
