555→/// Get role for a peer from their stored permit
556→///
557→/// **Context**: Determining role for Lua validation
558→/// **Checks**:
559→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
560→/// 2. Stored permit (node mode) -> extract role from permit
561→/// 3. Default -> "peer"
562→#[instrument(skip(state), fields(page_id = %state.page_id))]
563→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
564→    // If peer is our sync target, they are the "node" from our perspective
565→    if let Some(ref config) = state.sync_config {
566→        if let Some(ref sync_target) = config.sync_target {
567→            if sync_target == peer_did {
568→                return "node".to_string();
569→            }
570→        }
571→    }
572→
573→    // Node mode: look up peer's stored permit and extract role via PermitContext
574→    if let Some(ref resolver) = state.peer_resolver {
575→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
576→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
577→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
578→                .unwrap_or_else(|_| "peer".to_string());
579→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
580→            return role;
581→        }
582→    }
583→
584→    // Default role
585→    "peer".to_string()
586→}
