272→// Startup Observer Setup
273→
274→/// Set up Loro observers for all layers at Scribe startup
275→///
276→/// **Context**: Called from `pre_start` to ensure observers are ready before any updates
277→/// **Why**: Loro's `import()` triggers observers automatically, so we need them set up
278→/// **Handles**: Peer broadcasts (to subscribers) + UI notifications (to loro_observers)
279→///
280→/// This ensures both local changes (via commit) and remote changes (via import)
281→/// go through the same observer-based notification path.
282→#[instrument(skip_all, fields(page_id = %state.page_id))]
283→pub fn setup_observers_for_all_layers(state: &mut ScribeState) {
284→    let layer_names: Vec<String> = state.units.keys().cloned().collect();
285→
286→    for layer_name in layer_names {
287→        setup_layer_observer(state, &layer_name);
288→    }
289→
290→    let observer_count = state.units.values().filter(|u| u.has_observer()).count();
291→    info!(
292→        page_id = %state.page_id,
293→        layer_count = observer_count,
294→        "Set up Loro observers for all layers"
295→    );
296→}
297→
298→/// Set up Loro observer for a single layer
299→///
300→/// **Context**: Sets up the observer infrastructure for peer broadcasts and UI notifications
301→/// **Observer fires**: On commit() AND import() - both trigger subscribe_root
302→///
303→/// **Public**: Called from mod.rs when new layers are dynamically created
304→#[instrument(skip(state), fields(page_id = %state.page_id))]
305→pub fn setup_layer_observer(state: &mut ScribeState, layer_name: &str) {
306→    // Skip if already set up
307→    match state.units.get(layer_name) {
308→        Some(u) if u.has_observer() => return,
309→        Some(_) => {}
310→        None => {
311→            warn!(layer_name = %layer_name, "Layer not found for observer setup");
312→            return;
313→        }
314→    };
315→
316→    // We need to get the layer clone and is_local_only before borrowing state mutably
317→    let (layer_clone, is_local_only) = {
318→        let unit = state.units.get(layer_name).unwrap();
319→        (unit.layer().clone(), unit.is_local_only())
320→    };
321→
322→    // Create internal channel for observer signals (includes ops for reactive bindings)
323→    let (signal_tx, mut signal_rx) = tokio::sync::mpsc::unbounded_channel::<ObserverSignal>();
324→
325→    // Clone for the async task
326→    let layer_for_task = layer_clone.clone();
327→    let layer_name_for_task = layer_name.to_string();
328→    let page_id_for_task = state.page_id.clone();
329→    let page_update_subscribers_for_task = state.page_update_subscribers.clone();
330→    // Capture LayerUnit's subscriber map for broadcast filtering and sending
331→    let layer_subscribers_for_task = state.units.get(layer_name).unwrap().subscribers().clone();
332→    // Clone capture_tx for the observer task
333→    let capture_tx_for_task = state.capture_tx.clone();
334→
335→    // Clone pending_update_source for the synchronous callback
336→    let pending_update_source = state.pending_update_source.clone();
337→
338→    // Spawn async task to handle observer signals
339→    // Note: Derivation is handled in handle_apply_update using ops, not here
340→    tokio::spawn(async move {
341→        while let Some(signal) = signal_rx.recv().await {
342→            let state_vector = layer_for_task.version_vector();
343→
344→            // Prepare ops for reactive bindings (Some if non-empty, None otherwise)
345→            let ops = if signal.ops.is_empty() { None } else { Some(signal.ops) };
346→
347→            // Skip expensive get_content() only for List deltas (surgical conversion always works).
348→            // For Map/Text deltas, always provide full_data so non-keyed Map bindings can
349→            // fall back to Replace when delta conversion returns empty.
350→            let full_data = if matches!(&signal.delta, Some(LoroDelta::List { .. })) {
351→                None
352→            } else {
353→                Some(layer_for_task.get_content(&layer_name_for_task))
354→            };
355→
356→            let page_update = PageUpdate::LayerChanged {
357→                layer: layer_name_for_task.clone(),
358→                from_peer: None,  // Local change
359→                ops,
360→                delta: signal.delta,
361→                state_vector,
362→                full_data,
363→                created: false,
364→            };
365→            // Emit to capture channel (pre-serialized JSON line)
366→            if let Some(ref capture_tx) = capture_tx_for_task {
367→                let ts = std::time::SystemTime::now()
368→                    .duration_since(std::time::UNIX_EPOCH)
369→                    .map(|d| d.as_millis())
370→                    .unwrap_or(0);
371→                if let Ok(json) = serde_json::to_string(&serde_json::json!({
372→                    "type": "page_update",
373→                    "ts": ts,
374→                    "page_id": &page_id_for_task,
375→                    "data": &page_update,
376→                })) {
377→                    let _ = capture_tx.send(json);
378→                }
379→            }
380→            if let Ok(subs) = page_update_subscribers_for_task.read() {
381→                for tx in subs.iter() {
382→                    let _ = tx.try_send(page_update.clone());
383→                }
384→                if !subs.is_empty() {
385→                    debug!(
386→                        layer_name = %layer_name_for_task,
387→                        subscriber_count = subs.len(),
388→                        "Sent PageUpdate::LayerChanged"
389→                    );
390→                }
391→            }
392→
393→            // Check if layer is local-only (sync: false in permit)
394→            // Captured as bool at observer setup time — static per layer
395→            if is_local_only {
396→                if let Some(ref ctx) = capture_tx_for_task {
397→                    let ts = std::time::SystemTime::now()
398→                        .duration_since(std::time::UNIX_EPOCH)
399→                        .map(|d| d.as_millis())
400→                        .unwrap_or(0);
401→                    let _ = ctx.send(serde_json::json!({
402→                        "type": "broadcast_decision",
403→                        "ts": ts,
404→                        "page_id": &page_id_for_task,
405→                        "layer": &layer_name_for_task,
406→                        "decision": "skip",
407→                        "reason": "local_only",
408→                    }).to_string());
409→                }
410→                debug!(
411→                    layer_name = %layer_name_for_task,
412→                    "Skipping peer broadcast for local-only layer (sync: false)"
413→                );
414→                continue;
415→            }
416→
417→            // Skip peer broadcast for remote updates (sender exclusion)
418→            // Remote updates are forwarded via broadcast_update() in apply.rs which has proper sender exclusion
419→            // Broadcasting here would send the update back to the original sender, causing a sync storm
420→            if signal.from_peer.is_some() {
421→                if let Some(ref ctx) = capture_tx_for_task {
422→                    let ts = std::time::SystemTime::now()
423→                        .duration_since(std::time::UNIX_EPOCH)
424→                        .map(|d| d.as_millis())
425→                        .unwrap_or(0);
426→                    let _ = ctx.send(serde_json::json!({
427→                        "type": "broadcast_decision",
428→                        "ts": ts,
429→                        "page_id": &page_id_for_task,
430→                        "layer": &layer_name_for_task,
431→                        "decision": "skip",
432→                        "reason": "remote_handled_by_apply",
433→                    }).to_string());
434→                }
435→                debug!(
436→                    layer_name = %layer_name_for_task,
437→                    "Skipping observer peer broadcast for remote update (handled by broadcast_update)"
438→                );
439→                continue;
440→            }
441→
442→            // Broadcast incremental updates to layer subscribers
443→            // Uses per-subscriber version_vector for incremental export
444→            let current_vector = layer_for_task.version_vector();
445→
446→            if let Ok(layer_subs) = layer_subscribers_for_task.read() {
447→                info!(
448→                    page_id = %page_id_for_task,
449→                    layer_name = %layer_name_for_task,
450→                    subscriber_count = layer_subs.len(),
451→                    "Observer broadcasting local write to layer subscribers"
452→                );
453→                for (did, sub) in layer_subs.iter() {
454→                    // Check read capability (replaces authorized_dids check)
455→                    if !sub.capabilities.read {
456→                        if let Some(ref ctx) = capture_tx_for_task {
457→                            let ts = std::time::SystemTime::now()
458→                                .duration_since(std::time::UNIX_EPOCH)
459→                                .map(|d| d.as_millis())
460→                                .unwrap_or(0);
461→                            let _ = ctx.send(serde_json::json!({
462→                                "type": "broadcast_decision",
463→                                "ts": ts,
464→                                "page_id": &page_id_for_task,
465→                                "layer": &layer_name_for_task,
466→                                "peer_did": did,
467→                                "decision": "skip",
468→                                "reason": "no_read_capability",
469→                            }).to_string());
470→                        }
471→                        continue;
472→                    }
473→
474→                    // Incremental export: use subscriber's last known vector
475→                    // Falls back to full snapshot for first sync (no vector cached)
476→                    let update = if !sub.version_vector.is_empty() {
477→                        layer_for_task.export_updates(&sub.version_vector)
478→                            .unwrap_or_else(|_| layer_for_task.export_snapshot())
479→                    } else {
480→                        layer_for_task.export_snapshot()
481→                    };
482→
483→                    let update_size = update.len();
484→                    let payload = BroadcastPayload {
485→                        page_id: page_id_for_task.clone(),
486→                        layer_name: layer_name_for_task.clone(),
487→                        layer_type: domains::LayerType::from_layer_name(&layer_name_for_task),
488→                        update,
489→                        state_vector: current_vector.clone(),
490→                    };
491→
492→                    match sub.broadcast_tx.try_send(payload) {
493→                        Ok(()) => {
494→                            debug!(
495→                                user_did = %did,
496→                                layer_name = %layer_name_for_task,
497→                                update_size = update_size,
498→                                "Sent incremental broadcast to layer subscriber"
499→                            );
500→                        }
501→                        Err(mpsc::error::TrySendError::Full(_)) => {
502→                            warn!(user_did = %did, "Peer broadcast channel full");
503→                        }
504→                        Err(mpsc::error::TrySendError::Closed(_)) => {
505→                            debug!(user_did = %did, "Peer broadcast channel closed");
506→                        }
507→                    }
508→                }
509→            }
510→        }
511→        debug!(layer_name = %layer_name_for_task, "Observer task ended");
512→    });
513→
514→    // Subscribe to Loro changes - extract ops and delta for reactive bindings
515→    let subscription = layer_clone.subscribe_root(move |diff_event: loro::event::DiffEvent| {
516→        // Extract structured ops for reactive Lua bindings (surgical UI updates)
517→        let ops = diff_event_to_ops(&diff_event);
518→
519→        // Extract delta for legacy VecModel operations
520→        let delta = diff_event.events.first()
521→            .and_then(|container_diff| convert_loro_diff_to_delta(&container_diff.diff));
522→
523→        // Read pending_update_source to determine if this is a remote update
524→        // Remote updates should not trigger peer broadcast (handled by broadcast_update with sender exclusion)
525→        let from_peer = pending_update_source.lock().ok().and_then(|g| g.clone());
526→
527→        let _ = signal_tx.send(ObserverSignal { delta, ops, from_peer });
528→    });
529→
530→    // Store subscription in the LayerUnit
531→    if let Some(unit) = state.units.get_mut(layer_name) {
532→        unit.set_observer(subscription);
533→    }
534→    debug!(layer_name = %layer_name, "Set up Loro observer for layer");
535→}
536→
537→// Pending Update Source Helpers
538→
539→/// Set pending update source before import()
540→///
541→/// **Context**: Called in handle_apply_update before import()
542→/// **Usage**: Observer reads this to populate `from_peer` in PageEvent
543→pub fn set_pending_update_source(state: &ScribeState, from_peer: Option<(String, String)>) {
544→    if let Ok(mut guard) = state.pending_update_source.lock() {
545→        *guard = from_peer;
546→    }
547→}
548→
549→/// Clear pending update source after import()
550→///
551→/// **Context**: Called in handle_apply_update after import()
552→/// **Important**: Must be called to reset for next local operation
553→pub fn clear_pending_update_source(state: &ScribeState) {
554→    if let Ok(mut guard) = state.pending_update_source.lock() {
555→        *guard = None;
556→    }
557→}
