  1→//! Dynamic Layer Management
  2→//!
  3→//! Schema validation, path generation, and permit preparation for dynamic layers.
  4→//! Uses PermitIssuer trait — never touches signing keys directly.
  5→
  6→use tracing::{info, warn};
  7→
  8→use crate::state::ScribeState;
  9→use crate::storage::PermitIssuer;
 10→use crate::loro_observer;
 11→
 12→use super::LayerUnit;
 13→
 14→/// Handle CreateDynamicLayer message
 15→///
 16→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 17→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
 18→/// **Returns**: Full layer name (bare, without page_id prefix)
 19→pub fn handle_create_dynamic_layer(
 20→    state: &mut ScribeState,
 21→    schema_key: &str,
 22→    layer_id: &str,
 23→) -> Result<String, String> {
 24→    let permit = state.our_permit.as_ref()
 25→        .ok_or_else(|| "No permit available".to_string())?;
 26→
 27→    // Validate schema exists in our permit's dynamic_layer_schemas
 28→    let schemas = permit.dynamic_layer_schemas();
 29→    let schema = schemas
 30→        .get(schema_key)
 31→        .cloned()
 32→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 33→
 34→    // Generate full layer path with our DID
 35→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 36→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 37→    let full_name = format!("{}/{}", state.page_id, bare_path);
 38→
 39→    // Check if layer already exists
 40→    if state.units.contains_key(&bare_path) {
 41→        info!(layer = %bare_path, "Dynamic layer already exists");
 42→        return Ok(full_name);
 43→    }
 44→
 45→    // Create the layer
 46→    info!(
 47→        page_id = %state.page_id,
 48→        schema = %schema_key,
 49→        layer = %bare_path,
 50→        "Creating dynamic layer"
 51→    );
 52→    let mut unit = LayerUnit::new_empty();
 53→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 54→    unit.is_dynamic = true;
 55→    state.units.insert(bare_path.clone(), unit);
 56→    state.track_new_sync_layer_in_meta(&bare_path);
 57→
 58→    // Add all connected subscribers to the new layer
 59→    if let Ok(subs) = state.subscribers.read() {
 60→        for ((did, _), info) in subs.iter() {
 61→            if let Some(unit) = state.units.get(&bare_path) {
 62→                let caps = super::Capabilities { read: true, write: true, sync: true };
 63→                unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
 64→                state.emit_layer_auth_capture(&bare_path, did, "subscriber_added_on_create");
 65→            }
 66→        }
 67→    }
 68→
 69→    // Set up observer for the new layer
 70→    loro_observer::setup_layer_observer(state, &bare_path);
 71→
 72→    issue_creator_layer_authority_permits(state, &full_name, &schema);
 73→
 74→    Ok(full_name)
 75→}
 76→
 77→fn issue_creator_layer_authority_permits(
 78→    state: &ScribeState,
 79→    full_layer_name: &str,
 80→    schema: &gurkha::DynamicLayerSchema,
 81→) {
 82→    let Some(ref issuer) = state.permit_issuer else { return; };
 83→
 84→    let mut targets: Vec<String> = Vec::new();
 85→    if let Ok(subs) = state.subscribers.read() {
 86→        for ((did, _device), _info) in subs.iter() {
 87→            targets.push(did.clone());
 88→        }
 89→    }
 90→
 91→    let config = authority_config_from_template(schema);
 92→
 93→    for audience in targets {
 94→        match issuer.issue_layer_authority_permit(
 95→            &audience,
 96→            full_layer_name,
 97→            config.clone(),
 98→            None,
 99→            1,
100→        ) {
101→            Ok((_token, _cid)) => {
102→                info!(
103→                    page_id = %state.page_id,
104→                    layer = %full_layer_name,
105→                    audience = %audience,
106→                    "Issued creator layer authority permit"
107→                );
108→            }
109→            Err(e) => {
110→                warn!(
111→                    page_id = %state.page_id,
112→                    layer = %full_layer_name,
113→                    audience = %audience,
114→                    error = %e,
115→                    "Failed to issue creator layer authority permit"
116→                );
117→            }
118→        }
119→    }
120→}
121→
122→fn authority_config_from_template(
123→    schema: &gurkha::DynamicLayerSchema,
124→) -> gurkha::LayerConfig {
125→    let mut config = schema.permissions.clone();
126→
127→    if config.layer_type.is_none() && !schema.layer_type.is_empty() {
128→        config.layer_type = Some(schema.layer_type.clone());
129→    }
130→
131→    config
132→}
133→
134→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
135→///
136→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
137→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
138→///
139→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
140→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
141→    let parts: Vec<&str> = schema_key.split('/').collect();
142→    let mut result = Vec::new();
143→
144→    if parts.is_empty() {
145→        return format!("{}/{}", our_did, layer_id);
146→    }
147→
148→    // First segment: literal
149→    result.push(parts[0].to_string());
150→
151→    // Insert our DID as the second segment (namespace)
152→    result.push(our_did.to_string());
153→
154→    // Remaining segments: replace {id} with layer_id, keep literals
155→    for part in &parts[1..] {
156→        if *part == "{id}" {
157→            result.push(layer_id.to_string());
158→        } else {
159→            result.push(part.to_string());
160→        }
161→    }
162→
163→    result.join("/")
164→}
165→
166→/// Determine recipients and create layer permits for a new dynamic layer
167→///
168→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
169→/// **Returns**: Ready-to-send permits — courier just distributes them.
170→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
171→pub fn prepare_layer_permits(
172→    permit_issuer: &dyn PermitIssuer,
173→    page_id: &str,
174→    layer_name: &str,
175→    schema: &gurkha::DynamicLayerSchema,
176→    creator_did: &str,
177→    connected_peers: &[String],
178→) -> Result<Vec<(String, String)>, String> {
179→    let mut permits = Vec::new();
180→
181→    match schema.grant {
182→        gurkha::GrantType::Open => {
183→            // Open: all connected peers get the same permissions
184→            let perms = schema.permissions.clone();
185→            for did in connected_peers {
186→                match permit_issuer.issue_layer_permit(did, layer_name, perms.clone(), None) {
187→                    Ok((token, _cid)) => {
188→                        info!(
189→                            page_id = %page_id,
190→                            layer = %layer_name,
191→                            recipient = %did,
192→                            "Issued open layer permit"
193→                        );
194→                        permits.push((did.clone(), token));
195→                    }
196→                    Err(e) => {
197→                        warn!(
198→                            page_id = %page_id,
199→                            layer = %layer_name,
200→                            recipient = %did,
201→                            error = %e,
202→                            "Failed to issue layer permit"
203→                        );
204→                    }
205→                }
206→            }
207→        }
208→        gurkha::GrantType::Explicit => {
209→            // Explicit: authority-driven only (creator -> node permits).
210→            for audience_did in connected_peers {
211→                let Some((config, intent_cid)) = authority_layer_config_and_intent(
212→                    permit_issuer,
213→                    audience_did,
214→                    layer_name,
215→                    page_id,
216→                ) else {
217→                    continue;
218→                };
219→
220→                match permit_issuer.issue_layer_permit(
221→                    audience_did,
222→                    layer_name,
223→                    config,
224→                    Some(&intent_cid),
225→                ) {
226→                    Ok((token, _cid)) => {
227→                        info!(
228→                            page_id = %page_id,
229→                            layer = %layer_name,
230→                            audience = %audience_did,
231→                            creator = %creator_did,
232→                            "Issued explicit layer permit from authority"
233→                        );
234→                        permits.push((audience_did.clone(), token));
235→                    }
236→                    Err(e) => {
237→                        warn!(
238→                            page_id = %page_id,
239→                            layer = %layer_name,
240→                            audience = %audience_did,
241→                            error = %e,
242→                            "Failed to issue explicit layer permit from authority"
243→                        );
244→                    }
245→                }
246→            }
247→        }
248→    }
249→
250→    Ok(permits)
251→}
252→
253→/// Find matching dynamic schema for a layer received from a peer
254→///
255→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
256→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
257→pub fn find_matching_dynamic_schema<'a>(
258→    permit: &'a gurkha::Permit,
259→    layer_name: &str,
260→    page_id: &str,
261→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
262→    let schemas = permit.dynamic_layer_schemas();
263→    if schemas.is_empty() {
264→        return None;
265→    }
266→
267→    // Strip page_id prefix to get bare layer path
268→    let page_prefix = format!("{}/", page_id);
269→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
270→
271→    let path_parts: Vec<&str> = bare_path.split('/').collect();
272→
273→    // Path must have at least 3 segments: prefix/did/id[/suffix]
274→    if path_parts.len() < 3 {
275→        return None;
276→    }
277→
278→    // Second segment should be a DID (the creator)
279→    let potential_creator = path_parts[1];
280→    if !potential_creator.starts_with("did:") {
281→        return None;
282→    }
283→
284→    // Try each schema pattern
285→    for (schema_key, schema) in schemas {
286→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
287→
288→        // Dynamic path has one extra segment (DID) compared to pattern
289→        if path_parts.len() != pattern_parts.len() + 1 {
290→            continue;
291→        }
292→
293→        // First segment must match literally
294→        if path_parts[0] != pattern_parts[0] {
295→            continue;
296→        }
297→
298→        // path[2..] must match pattern[1..] (with {id} as wildcard)
299→        let mut matched = true;
300→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
301→            if *pat_seg != "{id}" && path_seg != pat_seg {
302→                matched = false;
303→                break;
304→            }
305→        }
306→
307→        if matched {
308→            return Some((schema_key, schema, potential_creator.to_string()));
309→        }
310→    }
311→
312→    None
313→}
314→
315→/// Validate that a layer path created by a peer matches their DID (namespace security)
316→///
317→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
318→/// that the creator's DID is in the layer path (prevents namespace forgery).
319→///
320→/// **Returns**: true if the layer path contains the sender's DID
321→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
322→    let page_prefix = format!("{}/", page_id);
323→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
324→
325→    // The creator's DID must be the second segment in the path
326→    let parts: Vec<&str> = bare_path.split('/').collect();
327→    if parts.len() < 2 {
328→        return false;
329→    }
330→
331→    parts[1] == sender_did
332→}
