334→/// Handle AddLayerAccess message
335→///
336→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
337→/// **We do**: Validate capability, require authority permit, issue permit if peer is subscribed
338→pub async fn handle_add_layer_access(
339→    state: &ScribeState,
340→    layer_name: &str,
341→    did: &str,
342→) -> Result<(), String> {
343→    // 1. Check our permit has manage_layer_access capability
344→    let permit = state.our_permit.as_ref().ok_or_else(|| {
345→        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
346→        "No permit".to_string()
347→    })?;
348→    if !permit.can_manage_layer_access() {
349→        warn!(
350→            page_id = %state.page_id,
351→            layer = %layer_name,
352→            audience = %did,
353→            "AddLayerAccess rejected: missing manage_layer_access capability"
354→        );
355→        return Err("No manage_layer_access capability".into());
356→    }
357→
358→    // 2. Resolve schema/config and permit issuer
359→    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
360→        warn!(
361→            page_id = %state.page_id,
362→            layer = %layer_name,
363→            audience = %did,
364→            "AddLayerAccess rejected: no permit issuer (not node mode)"
365→        );
366→        "No permit issuer (not node mode)".to_string()
367→    })?;
368→    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
369→        .ok_or_else(|| {
370→            warn!(
371→                page_id = %state.page_id,
372→                layer = %layer_name,
373→                audience = %did,
374→                "AddLayerAccess rejected: layer does not match dynamic schema"
375→            );
376→            "Layer does not match any dynamic schema".to_string()
377→        })?;
378→    if schema.grant != gurkha::GrantType::Explicit {
379→        warn!(
380→            page_id = %state.page_id,
381→            layer = %layer_name,
382→            audience = %did,
383→            "AddLayerAccess rejected: schema grant is not explicit"
384→        );
385→        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
386→    }
387→
388→    let (config, intent_cid, source) = if let Some((cfg, cid)) = authority_layer_config_and_intent(
389→        issuer.as_ref(),
390→        did,
391→        layer_name,
392→        &state.page_id,
393→    ) {
394→        (cfg, Some(cid), "authority")
395→    } else {
396→        let cfg = schema.permissions.clone();
397→        warn!(
398→            page_id = %state.page_id,
399→            layer = %layer_name,
400→            audience = %did,
401→            "No layer authority permit found; issuing access from schema permissions"
402→        );
403→        (cfg, None, "schema_permissions")
404→    };
405→
406→    // 3. Issue permit (stored by coordinator even if peer is offline)
407→    let mut new_permits = Vec::new();
408→    match issuer.issue_layer_permit(did, layer_name, config, intent_cid.as_deref()) {
409→        Ok((token, _cid)) => {
410→            info!(
411→                page_id = %state.page_id,
412→                layer = %layer_name,
413→                audience = %did,
414→                source = %source,
415→                "Issued layer permit via AddLayerAccess"
416→            );
417→            new_permits.push((did.to_string(), token));
418→        }
419→        Err(e) => {
420→            warn!(error = %e, "Failed to issue layer permit for AddLayerAccess");
421→        }
422→    }
423→
424→    // 4. Add DID as subscriber on the LayerUnit (if permit was issued)
425→    if let Some((recipient_did, _token)) = new_permits.first() {
426→        let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
427→        let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
428→            subs.iter()
429→                .find(|((d, _), _)| d == recipient_did)
430→                .map(|(_, info)| info.broadcast_tx.clone())
431→        });
432→        if let (Some(unit), Some(tx)) = (state.units.get(&bare_name), broadcast_tx) {
433→            let caps = super::Capabilities { read: true, write: true, sync: true };
434→            unit.add_subscriber(recipient_did.clone(), caps, tx);
435→            state.emit_layer_auth_capture(&bare_name, recipient_did, "subscriber_added_add_access");
436→        }
437→    }
438→
439→    // 5. Emit LayerAccessChanged for Coordinator to store/distribute permit
440→    if !new_permits.is_empty() {
441→        if let Some(ref sync_event_tx) = state.sync_event_tx {
442→            let event = crate::SyncEvent::LayerAccessChanged {
443→                page_id: state.page_id.clone(),
444→                layer_name: layer_name.to_string(),
445→                permits: new_permits,
446→            };
447→            state.emit_sync_event_capture(&event);
448→            if let Err(e) = sync_event_tx.send(event).await {
449→                warn!(error = %e, "Failed to emit LayerAccessChanged");
450→            }
451→        }
452→    }
453→
454→    Ok(())
455→}
