 13→/// Extract permit holder's DID from the permit's audience field
 14→fn extract_permit_holder_did(permit: &str, fallback_did: &str) -> String {
 15→    match gurkha::Permit::from_token(permit) {
 16→        Ok(parsed) => {
 17→            let raw_aud = parsed.parsed().audience().to_string();
 18→            if raw_aud.starts_with("did:key:") {
 19→                raw_aud
 20→            } else {
 21→                match herald::Identity::did_from_base64_pubkey(&raw_aud) {
 22→                    Ok(did) => did,
 23→                    Err(e) => {
 24→                        warn!(error = %e, raw_aud = %raw_aud, "Failed to convert audience to DID");
 25→                        raw_aud
 26→                    }
 27→                }
 28→            }
 29→        }
 30→        Err(e) => {
 31→            warn!(error = %e, "Failed to extract audience from permit");
 32→            fallback_did.to_string()
 33→        }
 34→    }
 35→}
 36→
 37→/// Handle peer subscription
 38→///
 39→/// Parses permit, stores connection info, adds subscriber to each accessible
 40→/// LayerUnit, sends initial state, and issues pending layer permits.
 41→#[instrument(skip(state, broadcast_tx, ephemeral_tx, permit_token), fields(page_id = %state.page_id))]
 42→pub async fn handle_subscribe(
 43→    state: &mut ScribeState,
 44→    user_did: String,
 45→    device_id: String,
 46→    broadcast_tx: mpsc::Sender<BroadcastPayload>,
 47→    ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
 48→    permit_token: String,
 49→) {
 50→    info!(user_did = %user_did, device_id = %device_id, "Peer subscribing");
 51→
 52→    let permit = match gurkha::Permit::from_token(&permit_token) {
 53→        Ok(p) => p,
 54→        Err(e) => {
 55→            warn!(error = ?e, "Failed to parse permit, rejecting subscription");
 56→            return;
 57→        }
 58→    };
 59→
 60→    let permit_holder_did = extract_permit_holder_did(&permit_token, &user_did);
 61→
 62→    let vectors = match state.vector_storage.load_vectors(&user_did, &device_id) {
 63→        Ok(Some(v)) => v.into_iter()
 64→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
 65→            .collect(),
 66→        Ok(None) => HashMap::new(),
 67→        Err(e) => {
 68→            warn!(error = %e, "Failed to load peer vectors");
 69→            HashMap::new()
 70→        }
 71→    };
 72→
 73→    let is_visible = permit.is_visible();
 74→    let can_see_others = permit.can_see_others();
 75→    let display_name = permit.display_name().map(String::from);
 76→
 77→    info!(
 78→        user_did = %user_did,
 79→        permit_holder_did = %permit_holder_did,
 80→        is_visible = is_visible,
 81→        layers = ?permit.layers().keys().collect::<Vec<_>>(),
 82→        "Subscription with permit"
 83→    );
 84→
 85→    if let Ok(mut subs) = state.subscribers.write() {
 86→        subs.insert(
 87→            (user_did.clone(), device_id.clone()),
 88→            SubscriberInfo {
 89→                permit: permit.clone(),
 90→                subscriber_did: permit_holder_did.clone(),
 91→                is_visible,
 92→                can_see_others,
 93→                display_name: display_name.clone(),
 94→                broadcast_tx: broadcast_tx.clone(),
 95→                ephemeral_tx,
 96→                vectors,
 97→            },
 98→        );
 99→    }
100→
101→    // Add subscriber to each accessible LayerUnit
102→    add_subscriber_to_layers(state, &user_did, &permit, &permit_holder_did, can_see_others, &broadcast_tx);
103→
104→    emit_peer_subscribed(state, &user_did);
105→
106→    send_initial_state_to_subscriber(state, &user_did, &device_id, &broadcast_tx).await;
107→
108→    issue_pending_layer_permits(state, &user_did, &device_id).await;
109→
110→    // Observability: list which layers this subscriber was added to
111→    let subscribed_layers: Vec<String> = state.units.iter()
112→        .filter(|(_, unit)| unit.can_push_to(&user_did))
113→        .map(|(name, _)| name.clone())
114→        .collect();
115→    state.emit_subscriber_state_capture(
116→        &user_did,
117→        &subscribed_layers,
118→        state.units.len(),
119→        can_see_others,
120→        is_visible,
121→    );
122→}
123→
124→/// Add subscriber to all LayerUnits they have access to (from page permit)
125→fn add_subscriber_to_layers(
126→    state: &ScribeState,
127→    user_did: &str,
128→    permit: &gurkha::Permit,
129→    permit_holder_did: &str,
130→    can_see_others: bool,
131→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
132→) {
133→    let sync_target = state.sync_config.as_ref().and_then(|cfg| cfg.sync_target.as_deref());
134→
135→    for (layer_name, unit) in &state.units {
136→        if unit.is_local_only() { continue; }
137→
138→        // Protocol sync meta: pairwise access
139→        if layer_name.starts_with("__sync_meta/") {
140→            let did_in_layer = layer_name.trim_start_matches("__sync_meta/");
141→            if user_did == did_in_layer || sync_target == Some(user_did) {
142→                let caps = Capabilities { read: true, write: true, sync: true };
143→                unit.add_subscriber(user_did.to_string(), caps, broadcast_tx.clone());
144→                state.emit_layer_auth_capture(layer_name, user_did, "subscriber_added_protocol_sync_meta");
145→            }
146→            continue;
147→        }
148→
149→        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !can_see_others {
150→            continue;
151→        }
152→
153→        if permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
154→            continue;
155→        }
156→
157→        if permit.can_read_layer(layer_name, &state.page_id, permit_holder_did) {
158→            let can_write = permit.can_write_layer(layer_name, &state.page_id, permit_holder_did);
159→            let caps = Capabilities { read: true, write: can_write, sync: true };
160→            unit.add_subscriber(user_did.to_string(), caps, broadcast_tx.clone());
161→            state.emit_layer_auth_capture(layer_name, user_did, "subscriber_added_page_permit");
162→        }
163→    }
164→}
