266→/// Issue pending layer permits for a newly subscribed peer (node mode only)
267→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
268→async fn issue_pending_layer_permits(
269→    state: &ScribeState,
270→    user_did: &str,
271→    _device_id: &str,
272→) {
273→    let Some(ref issuer) = state.permit_issuer else { return; };
274→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
275→
276→    // Get broadcast_tx for this subscriber from ScribeState.subscribers
277→    let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
278→        subs.iter()
279→            .find(|((did, _), _)| did == user_did)
280→            .map(|(_, info)| info.broadcast_tx.clone())
281→    });
282→
283→    let authority_permits = match issuer.list_layer_authority_permits_for_audience(user_did) {
284→        Ok(permits) => permits,
285→        Err(e) => {
286→            warn!(error = %e, "Failed to list layer authority permits");
287→            return;
288→        }
289→    };
290→
291→    for (layer_name, _version, authority_token) in authority_permits {
292→        let already_issued = match issuer.has_layer_access_permit(user_did, &layer_name) {
293→            Ok(v) => v,
294→            Err(e) => {
295→                warn!(error = %e, layer = %layer_name, "Failed to check existing layer permit");
296→                continue;
297→            }
298→        };
299→        if already_issued { continue; }
300→
301→        let Some(config) = authority_layer_config(&authority_token, &layer_name, &state.page_id) else {
302→            warn!(layer = %layer_name, "Authority permit missing layer config");
303→            continue;
304→        };
305→
306→        let intent_cid = match gurkha::crypto::get_permit_cid(&authority_token) {
307→            Ok(cid) => cid,
308→            Err(e) => {
309→                warn!(error = %e, layer = %layer_name, "Failed to compute authority permit CID");
310→                continue;
311→            }
312→        };
313→
314→        match issuer.issue_layer_permit(user_did, &layer_name, config, Some(&intent_cid)) {
315→            Ok((token, _cid)) => {
316→                let bare_name = normalize_layer_name(&layer_name, &state.page_id);
317→
318→                // Add subscriber to the LayerUnit if we have a broadcast_tx
319→                if let Some(ref tx) = broadcast_tx {
320→                    if let Some(unit) = state.units.get(&bare_name) {
321→                        let caps = Capabilities { read: true, write: true, sync: true };
322→                        unit.add_subscriber(user_did.to_string(), caps, tx.clone());
323→                        state.emit_layer_auth_capture(&bare_name, user_did, "subscriber_added_layer_permit");
324→                    }
325→                }
326→
327→                let event = SyncEvent::LayerAccessChanged {
328→                    page_id: state.page_id.clone(),
329→                    layer_name: layer_name.to_string(),
330→                    permits: vec![(user_did.to_string(), token)],
331→                };
332→                state.emit_sync_event_capture(&event);
333→                if let Err(e) = sync_event_tx.send(event).await {
334→                    warn!(error = %e, layer = %layer_name, "Failed to emit layer permit event");
335→                }
336→            }
337→            Err(e) => warn!(error = %e, layer = %layer_name, "Failed to issue layer permit"),
338→        }
339→    }
340→}
341→
342→fn authority_layer_config(
343→    authority_token: &str,
344→    layer_name: &str,
345→    page_id: &str,
346→) -> Option<gurkha::LayerConfig> {
347→    let parsed = gurkha::Permit::from_token(authority_token).ok()?;
348→
349→    if let Some(config) = parsed.layers().get(layer_name) {
350→        return Some(config.clone());
351→    }
352→
353→    let bare = normalize_layer_name(layer_name, page_id);
354→    if let Some(config) = parsed.layers().get(&bare) {
355→        return Some(config.clone());
356→    }
357→
358→    None
359→}
