 55→                    if did != our_did {
 56→                        recipients.insert(did);
 57→                    }
 58→                }
 59→            }
 60→            Ok(None) => {
 61→                // Open distribution: all peers with page access are recipients.
 62→                let all_users = match state.butler.store().list_authorized_users_for_page(page_id) {
 63→                    Ok(users) => users,
 64→                    Err(e) => {
 65→                        warn!(error = %e, "Failed to list authorized users for open fanout");
 66→                        return;
 67→                    }
 68→                };
 69→
 70→                for user_did in all_users {
 71→                    if user_did != our_did {
 72→                        recipients.insert(user_did);
 73→                    }
 74→                }
 75→            }
 76→            Err(e) => {
