async fn emit_dynamic_layer_permits(
    state: &ScribeState,
    layer_name: &str,
    from_peer: &(String, String),
) {
    // 1. Validate it matches a dynamic schema
    let Some((schema_key, schema, creator_did)) =
        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };

    // 2. Validate sender's DID matches path DID (namespace security)
    if from_peer.0 != creator_did { return; }

    // 3. Prepare permits (issues them immediately)
    let permits = prepare_layer_permits(
        permit_issuer,
        &state.page_id,
        &full_layer_name,
        schema,
        &creator_did,
        &connected_peers,
    )?;

    // 4. Emit SyncEvent::NewDynamicLayer with ready-to-send permits
    let event = SyncEvent::NewDynamicLayer {
        page_id: state.page_id.clone(),
        layer_name: full_layer_name,
        permits,
    };
    sync_event_tx.send(event).await?
}
```

