**B. Explicit Grant** - Only authority-driven (authority permit controls)
```rust
gurkha::GrantType::Explicit => {
    for audience_did in connected_peers {
        let Some((config, intent_cid)) = 
            authority_layer_config_and_intent(...)?
        else { continue; };

        let token = issuer.issue_layer_permit(
