```rust
async fn send_initial_state_to_subscriber(
    state: &ScribeState,
    user_did: &str,
    device_id: &str,
    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
) {
    // 1. Load their saved vectors from storage
    let peer_vectors = state.vector_storage.load_vectors(user_did, device_id)?;

    // 2. For each layer they have access to
    for (layer_name, unit) in &state.units {
        if !unit.can_push_to(user_did) { continue; }

        // 3. Decide: snapshot vs incremental update
        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
            if their_vector.is_empty() {
                layer.export_snapshot()  // First time
            } else {
                match layer.export_updates(their_vector) {
                    Ok(updates) if updates.is_empty() => continue,
                    Ok(updates) => updates,  // Incremental
                    Err(_) => layer.export_snapshot(),  // Fallback
                }
            }
        } else {
            layer.export_snapshot()  // No stored vector = first sync
        };

        // 4. Send BroadcastPayload
        let payload = BroadcastPayload {
            page_id: state.page_id.clone(),
            layer_name: layer_name.clone(),
            layer_type: domains::LayerType::from_layer_name(layer_name),
            update: data,
            state_vector: layer.version_vector(),
        };
        broadcast_tx.try_send(payload)?;
    }
}
```

