### 6. **Broadcast Update Flow**

**File**: `/home/abe/osvauld/scribe/src/sync/broadcast.rs` (lines 14-78)

**Function**: `broadcast_update()` - Sends updates to current subscribers

Called after:
- Local edit (Loro observer triggers)
- Remote update received (line 178 in apply.rs)

```rust
pub async fn broadcast_update(
    state: &mut ScribeState,
    layer_name: &str,
    from_peer: Option<&(String, String)>,
) {
    let unit = state.units.get(layer_name)?;
    let current_vector = unit.layer().version_vector();
    let sender_did = from_peer.map(|(did, _)| did.as_str());

    for (did, sub) in layer_subs.iter_mut() {
        // 1. Skip sender (prevent echo)
        if sender_did == Some(did.as_str()) { continue; }

        // 2. Check read capability
        if !sub.capabilities.read { continue; }

        // 3. Incremental export from their last vector
        let update = if !sub.version_vector.is_empty() {
            layer.export_updates(&sub.version_vector)
                .unwrap_or_else(|_| layer.export_snapshot())
        } else {
            layer.export_snapshot()
        };

        // 4. Send BroadcastPayload
        let payload = BroadcastPayload {
            page_id: state.page_id.clone(),
            layer_name: layer_name.to_string(),
            layer_type: domains::LayerType::from_layer_name(layer_name),
            update,
            state_vector: current_vector.clone(),
        };

        match sub.broadcast_tx.try_send(payload) {
            Ok(()) => { sub.version_vector = current_vector.clone(); }
            Err(TrySendError::Closed(_)) => { to_remove.push(did.clone()); }
            Err(TrySendError::Full(_)) => { /* log backpressure */ }
        }
    }

    // 5. Emit EnsureSync for unsubscribed targets
    emit_sync_events_for_missing_targets(state);
}
```

