pub fn setup_layer_observer(state: &mut ScribeState, layer_name: &str) {
    let subscription = layer_clone.subscribe_root(move |diff_event: DiffEvent| {
        let ops = diff_event_to_ops(&diff_event);  // For Lua validation
        let delta = convert_loro_diff_to_delta(&diff_event);  // For UI
        let from_peer = pending_update_source.lock().and_then(|g| g.clone());

        let _ = signal_tx.send(ObserverSignal { delta, ops, from_peer });
    });
}
```

