 37→/// Handle peer subscription
 38→///
 39→/// Parses permit, stores connection info, adds subscriber to each accessible
 40→/// LayerUnit, sends initial state, and issues pending layer permits.
 41→#[instrument(skip(state, broadcast_tx, ephemeral_tx, permit_token), fields(page_id = %state.page_id))]
 42→pub async fn handle_subscribe(
 43→    state: &mut ScribeState,
 44→    user_did: String,
 45→    device_id: String,
 46→    broadcast_tx: mpsc::Sender<BroadcastPayload>,
 47→    ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
 48→    permit_token: String,
 49→) {
 50→    info!(user_did = %user_did, device_id = %device_id, "Peer subscribing");
 51→
 52→    let permit = match gurkha::Permit::from_token(&permit_token) {
 53→        Ok(p) => p,
 54→        Err(e) => {
 55→            warn!(error = ?e, "Failed to parse permit, rejecting subscription");
 56→            return;
 57→        }
 58→    };
 59→
 60→    let permit_holder_did = extract_permit_holder_did(&permit_token, &user_did);
 61→
 62→    let vectors = match state.vector_storage.load_vectors(&user_did, &device_id) {
 63→        Ok(Some(v)) => v.into_iter()
 64→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
 65→            .collect(),
 66→        Ok(None) => HashMap::new(),
 67→        Err(e) => {
 68→            warn!(error = %e, "Failed to load peer vectors");
 69→            HashMap::new()
 70→        }
 71→    };
 72→
 73→    let is_visible = permit.is_visible();
 74→    let can_see_others = permit.can_see_others();
 75→    let display_name = permit.display_name().map(String::from);
 76→
 77→    info!(
 78→        user_did = %user_did,
 79→        permit_holder_did = %permit_holder_did,
 80→        is_visible = is_visible,
 81→        layers = ?permit.layers().keys().collect::<Vec<_>>(),
 82→        "Subscription with permit"
 83→    );
 84→
 85→    if let Ok(mut subs) = state.subscribers.write() {
 86→        subs.insert(
 87→            (user_did.clone(), device_id.clone()),
 88→            SubscriberInfo {
 89→                permit: permit.clone(),
 90→                subscriber_did: permit_holder_did.clone(),
 91→                is_visible,
 92→                can_see_others,
 93→                display_name: display_name.clone(),
 94→                broadcast_tx: broadcast_tx.clone(),
 95→                ephemeral_tx,
 96→                vectors,
 97→            },
 98→        );
 99→    }
100→
101→    // Add subscriber to each accessible LayerUnit
102→    add_subscriber_to_layers(state, &user_did, &permit, &permit_holder_did, can_see_others, &broadcast_tx);
103→
104→    emit_peer_subscribed(state, &user_did);
105→
106→    send_initial_state_to_subscriber(state, &user_did, &device_id, &broadcast_tx).await;
107→
108→    issue_pending_layer_permits(state, &user_did, &device_id).await;
109→
110→    // Observability: list which layers this subscriber was added to
111→    let subscribed_layers: Vec<String> = state.units.iter()
112→        .filter(|(_, unit)| unit.can_push_to(&user_did))
113→        .map(|(name, _)| name.clone())
114→        .collect();
115→    state.emit_subscriber_state_capture(
116→        &user_did,
117→        &subscribed_layers,
118→        state.units.len(),
119→        can_see_others,
120→        is_visible,
121→    );
122→}
